/**
 * Translator tests — cross-vocab translation correctness.
 *
 * Three layers of verification:
 *   1. Synthetic byte_level fixture round-trips with itself (identity translation).
 *   2. Real Qwen-2 → Qwen-2 (identity over a 152K-vocab production tokenizer)
 *      — proves the streaming buffering doesn't drop or duplicate text.
 *   3. Cross-vocab: real Qwen-2 → Llama-3 (when both maps are present locally)
 *      — sanity-checks that translated output detokenizes back to the
 *      original text under the target tokenizer.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

import {
  BPETokenizer,
  Detokenizer,
  Translator,
  staticTranslationTable,
  translate,
  type TokenizerMap,
} from '../src/index.ts';

// ── Synthetic identity translation ─────────────────────────────────────────

function findRealMap(family: 'qwen' | 'meta-llama'): string | null {
  const filename = family === 'qwen' ? 'qwen2.json' : 'llama-3.json';
  const candidates = [
    path.resolve('H:/dev/codec-maps/maps', family, filename),
    path.resolve(import.meta.dirname, '../../../../codec-maps/maps', family, filename),
    path.resolve(import.meta.dirname, '../../../../../codec-maps/maps', family, filename),
  ];
  for (const c of candidates) if (fs.existsSync(c)) return c;
  return null;
}

const QWEN_PATH  = findRealMap('qwen');
const LLAMA_PATH = findRealMap('meta-llama');

function loadMap(p: string): TokenizerMap {
  return JSON.parse(fs.readFileSync(p, 'utf-8'));
}

// ── Real Qwen-2 identity translation ──────────────────────────────────────

test(
  'Translator: real Qwen-2 → Qwen-2 identity round-trips through detokenize',
  { skip: !QWEN_PATH && 'codec-maps/qwen/qwen2.json not present' },
  () => {
    const map = loadMap(QWEN_PATH!);
    const tok = new BPETokenizer(map);
    const detok = new Detokenizer(map);
    const tr = new Translator(map, map);

    const samples = [
      'Hello, world!',
      'def add(a, b):\n    return a + b',
      'Multiple   spaces   between   words.',
      '🚀 launch',
      '日本語のテキスト',
      'Café résumé naïve façade',
    ];
    for (const s of samples) {
      const ids = tok.encode(s);
      const translated = tr.translate(ids);
      assert.equal(detok.render(translated), s,
        `identity round-trip failed for ${JSON.stringify(s)}`);
    }
  },
);

test(
  'Translator: streaming Qwen-2 → Qwen-2 yields the same final IDs as one-shot',
  { skip: !QWEN_PATH && 'codec-maps/qwen/qwen2.json not present' },
  () => {
    const map = loadMap(QWEN_PATH!);
    const tok = new BPETokenizer(map);
    const tr = new Translator(map, map);
    const detok = new Detokenizer(map);

    const text = 'The quick brown fox jumps over the lazy dog. ' +
                 'Pack my box with five dozen liquor jugs.';
    const ids = tok.encode(text);

    // Feed in 3-token chunks with partial=true, then a final partial=false flush.
    const collected: number[] = [];
    const chunkSize = 3;
    for (let i = 0; i < ids.length; i += chunkSize) {
      const chunk = ids.slice(i, i + chunkSize);
      const isLast = i + chunkSize >= ids.length;
      const out = tr.translate(chunk, { partial: !isLast });
      collected.push(...out);
    }
    // After the final chunk with partial=false there should be no buffered residue.
    assert.equal(detok.render(collected), text);
  },
);

// ── Cross-vocab: Qwen-2 → Llama-3 ─────────────────────────────────────────

test(
  'Translator: Qwen-2 → Llama-3 cross-vocab translation round-trips',
  {
    skip: (!QWEN_PATH || !LLAMA_PATH) &&
      'requires both codec-maps/qwen/qwen2.json and codec-maps/meta-llama/llama-3.json',
  },
  () => {
    const qwen  = loadMap(QWEN_PATH!);
    const llama = loadMap(LLAMA_PATH!);

    const qwenTok    = new BPETokenizer(qwen);
    const llamaDetok = new Detokenizer(llama);
    const tr         = new Translator(qwen, llama);

    const samples = [
      'Hello, world!',
      'def add(a, b):\n    return a + b',
      'Explain entropy in one sentence.',
      'Multiple   spaces.',
    ];
    for (const s of samples) {
      const qwenIds  = qwenTok.encode(s);
      const llamaIds = tr.translate(qwenIds);
      const text     = llamaDetok.render(llamaIds);
      assert.equal(text, s,
        `Qwen→Llama round-trip failed for ${JSON.stringify(s)}`);
    }
  },
);

// ── translate() one-shot helper ───────────────────────────────────────────

test(
  'translate(): one-shot helper produces same IDs as new Translator(...).translate(ids)',
  { skip: !QWEN_PATH && 'codec-maps/qwen/qwen2.json not present' },
  () => {
    const map = loadMap(QWEN_PATH!);
    const tok = new BPETokenizer(map);
    const ids = tok.encode('Identity check.');
    const a = translate(map, map, ids);
    const b = new Translator(map, map).translate(ids);
    assert.deepEqual(a, b);
  },
);

// ── Static translation table ──────────────────────────────────────────────

test(
  'staticTranslationTable: covers every non-special source vocab entry',
  { skip: !QWEN_PATH && 'codec-maps/qwen/qwen2.json not present' },
  () => {
    const map = loadMap(QWEN_PATH!);
    const table = staticTranslationTable(map, map);
    // Every non-special token should map to a non-empty target sequence.
    const specialIds = new Set(Object.values(map.special_tokens ?? {}));
    let nonSpecialCount = 0;
    let coveredCount = 0;
    for (const id of Object.values(map.vocab ?? {})) {
      if (specialIds.has(id)) continue;
      nonSpecialCount++;
      if (table.has(id)) coveredCount++;
    }
    // Allow a small margin for byte-fallback / control tokens whose decoded
    // text is empty or unrenderable; the bulk should be covered.
    const coverage = coveredCount / nonSpecialCount;
    assert.ok(coverage > 0.99,
      `expected >99% coverage, got ${(coverage * 100).toFixed(2)}%`);
  },
);

test(
  'staticTranslationTable: identity translation maps each ID to a sequence containing itself',
  { skip: !QWEN_PATH && 'codec-maps/qwen/qwen2.json not present' },
  () => {
    const map = loadMap(QWEN_PATH!);
    const table = staticTranslationTable(map, map);

    // Pick a few common tokens and verify the table maps them to themselves
    // (this is the byte_level invariant: re-tokenizing a token's own decoded
    // text yields that same single token, when it's a complete BPE token).
    const sampleKeys = ['Hello', 'world', '!'];
    for (const key of sampleKeys) {
      const id = (map.vocab ?? {})[key];
      if (id === undefined) continue;
      const out = table.get(id);
      assert.ok(out !== undefined && out.length === 1 && out[0] === id,
        `expected ${key} (id ${id}) → [${id}], got ${JSON.stringify(out)}`);
    }
  },
);

/**
 * @codecai/web — isomorphic tokenizer + detokenizer for the Codec binary
 * transport protocol.
 *
 * Loads per-model tokenizer dialect maps, tokenizes text at the edge before
 * transport, and detokenizes IDs to text only when a human is going to read
 * them. Agent-to-agent calls skip detokenization entirely — text never
 * enters the transport at all.
 *
 * Works in browsers, Node 18+, Cloudflare Workers, Deno, Bun. No Node-only
 * imports. No transitive heavyweight dependencies.
 *
 * Quick start (decoding a stream):
 *
 *   import { loadMap, Detokenizer, decodeStream } from '@codecai/web';
 *
 *   const map = await loadMap({
 *     url: 'https://cdn.jsdelivr.net/gh/wdunn001/codec-maps/maps/meta-llama/llama-3.json',
 *     hash: 'sha256:…',
 *   });
 *   const detok = new Detokenizer(map);
 *   for await (const frame of decodeStream(resp.body!)) {
 *     output.append(detok.render(frame.ids, { partial: !frame.done }));
 *   }
 *
 * Quick start (encoding text for the bidirectional endpoint):
 *
 *   import { BPETokenizer } from '@codecai/web';
 *   const tok = new BPETokenizer(map);
 *   const ids = tok.encode('Explain entropy.');
 *   // send `ids` over the wire as msgpack/protobuf — never text.
 */
export type {
  TokenizerMap,
  ToolCallingBlock,
  CodecFrame,
  FinishReason,
  MapCache,
  Tokenizer,
  SafetyPolicyDescriptor,
  SafetyPolicyCategory,
  SafetyPolicyClassifier,
  SafetyPolicyRulesSummary,
  SafetyPolicyClientHooks,
  SafetyPolicyPublisher,
  SafetyPolicyCache,
} from './types.js';

export {
  validateSafetyPolicy,
  hashSafetyPolicy,
  loadSafetyPolicy,
  discoverSafetyPolicy,
  wellKnownPolicyUrl,
  wellKnownPolicyHashUrl,
  POLICY_WELL_KNOWN_BASE,
  MemorySafetyPolicyCache,
  SafetyPolicyValidationError,
  SafetyPolicyHashMismatchError,
  SafetyPolicyDiscoveryError,
  SafetyPolicyDiscoveryNotFoundError,
  type LoadSafetyPolicyOptions,
  type DiscoverSafetyPolicyOptions,
  type SafetyPolicyPointer,
} from './safety-policy.js';

export {
  loadMap,
  makeMap,
  validateMap,
  MemoryMapCache,
  TokenizerMapValidationError,
  TokenizerMapHashMismatchError,
  type LoadOptions,
} from './map.js';

export {
  discoverMap,
  discoverIndex,
  wellKnownMapUrl,
  wellKnownIndexUrl,
  WELL_KNOWN_BASE,
  MapDiscoveryError,
  MapDiscoveryNotFoundError,
  type MapPointer,
  type MapIndex,
  type DiscoverMapOptions,
  type DiscoverIndexOptions,
} from './discover.js';

export {
  Detokenizer,
  detokenize,
  type DetokenizeOptions,
} from './detokenize.js';

export {
  LongestMatchTokenizer,
  tokenize,
  pickTokenizer,
} from './tokenize.js';

export {
  Translator,
  translate,
  staticTranslationTable,
  type TranslateOptions,
} from './translate.js';

export {
  ToolWatcher,
  ToolWatcherError,
  type WatcherEvent,
} from './tool-watcher.js';

export {
  BPETokenizer,
  bpeEncode,
} from './bpe.js';

export {
  BYTE_TO_CHAR,
  CHAR_TO_BYTE,
  decodeByteLevelToken,
  encodeByteLevelChars,
  METASPACE,
} from './encoder.js';

export {
  decodeStream,
  decodeMsgpackStream,
  decodeProtobufStream,
  decodeProtobufFrame,
} from './stream.js';

export {
  runPreTokProgram,
  type PreTokOp,
  type PreTokProgram,
} from './pretok-program.js';

// Latent modality (v0.3) — TypeScript twin of
// packages/python/src/codecai/server/latent_frame.py. Forward encoder +
// inverse decoder + msgpack codec for all 7 pipelines (raw / int8 / int4 /
// int8-adaptive / int4-adaptive / delta+int8 / delta+int4). Pin: spec/
// PIPELINES.md is the normative reference; conformance fixtures live at
// packages/bench/golden/pipelines/<name>/.
export {
  PIPELINE_NAMES,
  LatentStreamEncoder,
  LatentStreamDecoder,
  encodeLatentHeaderMsgpack,
  encodeLatentFrameMsgpack,
  decodeLatentHeaderMsgpack,
  decodeLatentFrameMsgpack,
  scalesToBytes,
  scalesFromBytes,
  packInt4LowFirst,
  unpackInt4LowFirst,
  computeScales,
  type PipelineName,
  type LatentDtype,
  type LatentStreamHeader,
  type LatentFrame,
  type LatentStreamEncoderOptions,
} from './latent-frame.js';

/**
 * Safety-policy descriptor loading, validation, and discovery.
 *
 * Mirrors the tokenizer-map (`map.ts` / `discover.ts`) shape: validate, hash,
 * fetch, cache, well-known. A `SafetyPolicyDescriptor` is the *sanitized,
 * publishable* document an operator publishes at
 * `.well-known/codec/policies/<id>.json` (or `<hash>.json`) — never the
 * full operator-internal config. See `spec/safety-policy.schema.json`.
 *
 * Used by clients that received `safety_policy_id` + `safety_policy_hash`
 * in `READY` and want to fetch and surface what the server is enforcing.
 */
import type {
  SafetyPolicyCache,
  SafetyPolicyCategory,
  SafetyPolicyDescriptor,
} from './types.js';

// ── Pluggable cache (default: in-memory) ──────────────────────────────────────

export class MemorySafetyPolicyCache implements SafetyPolicyCache {
  private store = new Map<string, SafetyPolicyDescriptor>();
  async get(key: string): Promise<SafetyPolicyDescriptor | undefined> {
    return this.store.get(key);
  }
  async set(key: string, descriptor: SafetyPolicyDescriptor): Promise<void> {
    this.store.set(key, descriptor);
  }
}

const defaultCache: SafetyPolicyCache = new MemorySafetyPolicyCache();

// ── Validation ────────────────────────────────────────────────────────────────
//
// Hand-written shape check, matching `validateMap` in map.ts. We don't pull
// a JSON-Schema validator into the wire path; the contract is small enough
// that an explicit check is honest about what we actually require.

export class SafetyPolicyValidationError extends Error {
  constructor(message: string) {
    super(`SafetyPolicyDescriptor validation failed: ${message}`);
    this.name = 'SafetyPolicyValidationError';
  }
}

const VALID_ACTIONS = new Set<SafetyPolicyCategory['action']>([
  'stop',
  'redact',
  'regenerate',
  'flag',
]);

const VALID_HOSTS = new Set(['server', 'client', 'both']);

const VALID_ENGINE_FEATURES = new Set([
  'logits_processor',
  'hidden_states',
  'sampling_chain',
]);

const CATEGORY_NAME_RE = /^[a-z0-9_-]+$/;

export function validateSafetyPolicy(
  value: unknown,
): asserts value is SafetyPolicyDescriptor {
  if (typeof value !== 'object' || value === null) {
    throw new SafetyPolicyValidationError('not an object');
  }
  const p = value as Record<string, unknown>;

  if (typeof p.id !== 'string' || p.id.length === 0) {
    throw new SafetyPolicyValidationError('id must be a non-empty string');
  }
  if (typeof p.version !== 'string') {
    throw new SafetyPolicyValidationError('version must be a string');
  }

  if (!Array.isArray(p.tokenizers) || p.tokenizers.length === 0) {
    throw new SafetyPolicyValidationError(
      'tokenizers must be a non-empty array of tokenizer ids',
    );
  }
  for (const t of p.tokenizers) {
    if (typeof t !== 'string') {
      throw new SafetyPolicyValidationError(
        'tokenizers entries must be strings',
      );
    }
  }

  if (!Array.isArray(p.categories) || p.categories.length === 0) {
    throw new SafetyPolicyValidationError(
      'categories must be a non-empty array',
    );
  }
  for (const c of p.categories) {
    if (typeof c !== 'object' || c === null) {
      throw new SafetyPolicyValidationError('category entry must be an object');
    }
    const cat = c as Record<string, unknown>;
    if (typeof cat.name !== 'string' || !CATEGORY_NAME_RE.test(cat.name)) {
      throw new SafetyPolicyValidationError(
        `category.name must match ${CATEGORY_NAME_RE} (got ${JSON.stringify(cat.name)})`,
      );
    }
    if (
      typeof cat.action !== 'string' ||
      !VALID_ACTIONS.has(cat.action as SafetyPolicyCategory['action'])
    ) {
      throw new SafetyPolicyValidationError(
        `category.action for ${JSON.stringify(cat.name)} must be one of stop|redact|regenerate|flag`,
      );
    }
    if (cat.description !== undefined && typeof cat.description !== 'string') {
      throw new SafetyPolicyValidationError(
        `category.description for ${JSON.stringify(cat.name)} must be a string when present`,
      );
    }
  }

  if (typeof p.classifier !== 'object' || p.classifier === null) {
    throw new SafetyPolicyValidationError('classifier must be an object');
  }
  const cls = p.classifier as Record<string, unknown>;
  if (typeof cls.family !== 'string' || cls.family.length === 0) {
    throw new SafetyPolicyValidationError(
      'classifier.family must be a non-empty string',
    );
  }
  if (cls.host !== undefined && (typeof cls.host !== 'string' || !VALID_HOSTS.has(cls.host))) {
    throw new SafetyPolicyValidationError(
      `classifier.host must be one of server|client|both (got ${JSON.stringify(cls.host)})`,
    );
  }
  if (cls.requires_engine_features !== undefined) {
    if (!Array.isArray(cls.requires_engine_features)) {
      throw new SafetyPolicyValidationError(
        'classifier.requires_engine_features must be an array',
      );
    }
    for (const f of cls.requires_engine_features) {
      if (typeof f !== 'string' || !VALID_ENGINE_FEATURES.has(f)) {
        throw new SafetyPolicyValidationError(
          `classifier.requires_engine_features entry must be one of logits_processor|hidden_states|sampling_chain (got ${JSON.stringify(f)})`,
        );
      }
    }
  }

  if (p.rules_summary !== undefined) {
    if (typeof p.rules_summary !== 'object' || p.rules_summary === null) {
      throw new SafetyPolicyValidationError('rules_summary must be an object when present');
    }
    const rs = p.rules_summary as Record<string, unknown>;
    for (const key of [
      'banned_token_id_count',
      'regex_pattern_count',
      'grammar_constraint_count',
      'multi_token_pattern_count',
    ] as const) {
      const val = rs[key];
      if (val !== undefined && (typeof val !== 'number' || val < 0 || !Number.isInteger(val))) {
        throw new SafetyPolicyValidationError(
          `rules_summary.${key} must be a non-negative integer when present`,
        );
      }
    }
  }

  if (p.client_hooks !== undefined) {
    if (typeof p.client_hooks !== 'object' || p.client_hooks === null) {
      throw new SafetyPolicyValidationError('client_hooks must be an object when present');
    }
    const ch = p.client_hooks as Record<string, unknown>;
    if (ch.prefilter_categories !== undefined) {
      if (!Array.isArray(ch.prefilter_categories)) {
        throw new SafetyPolicyValidationError(
          'client_hooks.prefilter_categories must be an array of strings',
        );
      }
      for (const c of ch.prefilter_categories) {
        if (typeof c !== 'string') {
          throw new SafetyPolicyValidationError(
            'client_hooks.prefilter_categories entries must be strings',
          );
        }
      }
    }
    if (
      ch.client_classifier_family !== undefined &&
      typeof ch.client_classifier_family !== 'string'
    ) {
      throw new SafetyPolicyValidationError(
        'client_hooks.client_classifier_family must be a string when present',
      );
    }
  }

  if (p.category_registry !== undefined && typeof p.category_registry !== 'string') {
    throw new SafetyPolicyValidationError(
      'category_registry must be a string when present',
    );
  }

  if (p.published_at !== undefined && typeof p.published_at !== 'string') {
    throw new SafetyPolicyValidationError(
      'published_at must be an ISO 8601 string when present',
    );
  }

  if (p.publisher !== undefined) {
    if (typeof p.publisher !== 'object' || p.publisher === null) {
      throw new SafetyPolicyValidationError('publisher must be an object when present');
    }
    const pub = p.publisher as Record<string, unknown>;
    for (const key of ['name', 'url', 'contact'] as const) {
      if (pub[key] !== undefined && typeof pub[key] !== 'string') {
        throw new SafetyPolicyValidationError(
          `publisher.${key} must be a string when present`,
        );
      }
    }
  }
}

// ── Hashing ──────────────────────────────────────────────────────────────────
//
// The published descriptor is content-addressed; the hash of its canonical
// JSON serialization is what `READY.safety_policy_hash` carries. We hash the
// pretty-printed JSON used at publish time (matching `well-known` output) so
// the hash a client receives matches what `policies hash` produced.

export class SafetyPolicyHashMismatchError extends Error {
  constructor(expected: string, actual: string) {
    super(
      `SafetyPolicyDescriptor hash mismatch.\n  expected: ${expected}\n  actual:   ${actual}`,
    );
    this.name = 'SafetyPolicyHashMismatchError';
  }
}

async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const subtle = (globalThis as { crypto?: { subtle?: SubtleCrypto } }).crypto?.subtle;
  if (!subtle) {
    throw new Error(
      '@codecai/web requires a SubtleCrypto implementation (Web Crypto API). ' +
        'Available in browsers, Node 18+, Cloudflare Workers, Deno.',
    );
  }
  const digest = await subtle.digest(
    'SHA-256',
    bytes.buffer.slice(
      bytes.byteOffset,
      bytes.byteOffset + bytes.byteLength,
    ) as ArrayBuffer,
  );
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function parseHash(hash: string): string {
  const colon = hash.indexOf(':');
  if (colon === -1) return hash.toLowerCase();
  const algo = hash.slice(0, colon).toLowerCase();
  if (algo !== 'sha256') {
    throw new Error(`Unsupported hash algorithm: ${algo} (only sha256 supported)`);
  }
  return hash.slice(colon + 1).toLowerCase();
}

/**
 * Canonical sha256 hash of a safety-policy descriptor. Matches what the
 * `codecai-maps policies hash` CLI emits and what servers should publish
 * in `READY.safety_policy_hash`.
 */
export async function hashSafetyPolicy(
  descriptor: SafetyPolicyDescriptor,
): Promise<string> {
  validateSafetyPolicy(descriptor);
  const canonical = JSON.stringify(descriptor, null, 2) + '\n';
  const bytes = new TextEncoder().encode(canonical);
  return `sha256:${await sha256Hex(bytes)}`;
}

// ── Loader ───────────────────────────────────────────────────────────────────

export interface LoadSafetyPolicyOptions {
  url: string;
  /** Expected hash (`sha256:<hex>` or bare `<hex>`). Verified after fetch. */
  hash?: string;
  cache?: SafetyPolicyCache;
  signal?: AbortSignal;
  fetchImpl?: typeof fetch;
  cacheKey?: string;
}

export async function loadSafetyPolicy(
  opts: LoadSafetyPolicyOptions,
): Promise<SafetyPolicyDescriptor> {
  const cache = opts.cache ?? defaultCache;
  const cacheKey = opts.cacheKey ?? `${opts.url}#${opts.hash ?? ''}`;

  const cached = await cache.get(cacheKey);
  if (cached) return cached;

  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error(
      '@codecai/web: no global fetch available. Pass `fetchImpl` or upgrade to Node 18+.',
    );
  }

  const resp = await fetchImpl(opts.url, { signal: opts.signal });
  if (!resp.ok) {
    throw new Error(
      `Failed to fetch safety policy from ${opts.url}: HTTP ${resp.status}`,
    );
  }
  const bytes = new Uint8Array(await resp.arrayBuffer());

  if (opts.hash) {
    const expected = parseHash(opts.hash);
    const actual = await sha256Hex(bytes);
    if (expected !== actual) {
      throw new SafetyPolicyHashMismatchError(expected, actual);
    }
  }

  const text = new TextDecoder().decode(bytes);
  const parsed: unknown = JSON.parse(text);
  validateSafetyPolicy(parsed);

  await cache.set(cacheKey, parsed);
  return parsed;
}

// ── Discovery ────────────────────────────────────────────────────────────────

export const POLICY_WELL_KNOWN_BASE = '/.well-known/codec/policies';

/** Per-policy URL by mutable id (e.g. `acme/strict-v3`). */
export function wellKnownPolicyUrl(origin: string, id: string): string {
  return `${stripTrailingSlash(origin)}${POLICY_WELL_KNOWN_BASE}/${encodePolicyId(id)}.json`;
}

/** Content-addressed URL by sha256 hex (no `sha256:` prefix). */
export function wellKnownPolicyHashUrl(origin: string, hashHex: string): string {
  if (!/^[0-9a-f]{64}$/i.test(hashHex)) {
    throw new SafetyPolicyDiscoveryError(
      `Invalid policy hash hex: must be 64-char lowercase hex (got ${JSON.stringify(hashHex)})`,
    );
  }
  return `${stripTrailingSlash(origin)}${POLICY_WELL_KNOWN_BASE}/sha256/${hashHex.toLowerCase()}.json`;
}

function stripTrailingSlash(s: string): string {
  return s.endsWith('/') ? s.slice(0, -1) : s;
}

function encodePolicyId(id: string): string {
  if (!/^[a-z0-9._/-]+$/.test(id)) {
    throw new SafetyPolicyDiscoveryError(
      `Invalid policy id ${JSON.stringify(id)}: must match [a-z0-9._/-]+`,
    );
  }
  if (id.includes('..') || id.startsWith('/') || id.endsWith('/')) {
    throw new SafetyPolicyDiscoveryError(
      `Invalid policy id ${JSON.stringify(id)}: path traversal or empty segment`,
    );
  }
  return id;
}

/** Pointer document at `.well-known/codec/policies/<id>.json` (Form A). */
export interface SafetyPolicyPointer {
  readonly id: string;
  readonly url: string;
  readonly hash: string;
  readonly published_at?: string;
}

export class SafetyPolicyDiscoveryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SafetyPolicyDiscoveryError';
  }
}

export class SafetyPolicyDiscoveryNotFoundError extends SafetyPolicyDiscoveryError {
  constructor(url: string, status: number) {
    super(`No safety-policy document at ${url} (HTTP ${status})`);
    this.name = 'SafetyPolicyDiscoveryNotFoundError';
  }
}

function isPointerShape(obj: unknown): obj is SafetyPolicyPointer {
  if (typeof obj !== 'object' || obj === null) return false;
  const o = obj as Record<string, unknown>;
  return (
    typeof o.id === 'string' &&
    typeof o.url === 'string' &&
    typeof o.hash === 'string' &&
    // Inline descriptors always carry `categories`; pointers never do.
    o.categories === undefined
  );
}

function validatePointer(obj: SafetyPolicyPointer, expectedId: string): void {
  if (obj.id !== expectedId) {
    throw new SafetyPolicyDiscoveryError(
      `Pointer id ${JSON.stringify(obj.id)} does not match requested id ${JSON.stringify(expectedId)}`,
    );
  }
  let parsed: URL;
  try {
    parsed = new URL(obj.url);
  } catch {
    throw new SafetyPolicyDiscoveryError(
      `Pointer url is not a valid URL: ${obj.url}`,
    );
  }
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new SafetyPolicyDiscoveryError(
      `Pointer url must be http(s): got ${parsed.protocol}`,
    );
  }
  if (!/^sha256:[0-9a-f]{64}$/i.test(obj.hash)) {
    throw new SafetyPolicyDiscoveryError(
      `Pointer hash must be sha256:<64 hex chars>: got ${obj.hash}`,
    );
  }
}

export interface DiscoverSafetyPolicyOptions {
  /** HTTPS origin publishing the policy (e.g. `https://acme.example`). */
  origin: string;
  /** Codec policy id (e.g. `acme/strict-v3`). */
  id: string;
  /**
   * Optional content hash — if provided, the loader prefers the
   * content-addressed `.well-known/codec/policies/sha256/<hex>.json`
   * sibling and verifies the bytes match.
   */
  hash?: string;
  cache?: SafetyPolicyCache;
  signal?: AbortSignal;
  fetchImpl?: typeof fetch;
}

/**
 * Resolve a safety-policy descriptor via `.well-known/codec/policies/`.
 *
 * If `hash` is provided, fetches the immutable content-addressed sibling
 * `<origin>/.well-known/codec/policies/sha256/<hex>.json` and verifies the
 * bytes hash matches. Otherwise fetches the mutable per-id document and
 * follows a pointer if present.
 *
 *   const policy = await discoverSafetyPolicy({
 *     origin: 'https://acme.example',
 *     id: 'acme/strict-v3',
 *     hash: 'sha256:abc...',
 *   });
 */
export async function discoverSafetyPolicy(
  opts: DiscoverSafetyPolicyOptions,
): Promise<SafetyPolicyDescriptor> {
  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new SafetyPolicyDiscoveryError(
      '@codecai/web: no global fetch available. Pass `fetchImpl` or upgrade to Node 18+.',
    );
  }

  // Hash present: prefer the immutable sibling. The bytes are the inline
  // descriptor (or a pointer that hashes to its filename's hex — but the
  // recommended layout is inline at the content-addressed path).
  if (opts.hash) {
    const hashHex = parseHash(opts.hash);
    const url = wellKnownPolicyHashUrl(opts.origin, hashHex);
    const resp = await fetchImpl(url, { signal: opts.signal });
    if (resp.status === 404) {
      throw new SafetyPolicyDiscoveryNotFoundError(url, resp.status);
    }
    if (!resp.ok) {
      throw new SafetyPolicyDiscoveryError(
        `Failed to fetch ${url}: HTTP ${resp.status}`,
      );
    }
    const bytes = new Uint8Array(await resp.arrayBuffer());
    const actual = await sha256Hex(bytes);
    if (actual !== hashHex) {
      throw new SafetyPolicyHashMismatchError(hashHex, actual);
    }
    const text = new TextDecoder().decode(bytes);
    const parsed: unknown = JSON.parse(text);
    if (isPointerShape(parsed)) {
      validatePointer(parsed, opts.id);
      return loadSafetyPolicy({
        url: parsed.url,
        hash: parsed.hash,
        cache: opts.cache,
        signal: opts.signal,
        fetchImpl: opts.fetchImpl,
        cacheKey: `well-known:${opts.origin}#${opts.id}#${parsed.hash}`,
      });
    }
    validateSafetyPolicy(parsed);
    if (parsed.id !== opts.id) {
      throw new SafetyPolicyDiscoveryError(
        `Inline descriptor id ${JSON.stringify(parsed.id)} does not match requested id ${JSON.stringify(opts.id)}`,
      );
    }
    return parsed;
  }

  // No hash: fetch the mutable per-id document and follow a pointer if present.
  const url = wellKnownPolicyUrl(opts.origin, opts.id);
  const resp = await fetchImpl(url, { signal: opts.signal });
  if (resp.status === 404) {
    throw new SafetyPolicyDiscoveryNotFoundError(url, resp.status);
  }
  if (!resp.ok) {
    throw new SafetyPolicyDiscoveryError(
      `Failed to fetch ${url}: HTTP ${resp.status}`,
    );
  }
  const parsed: unknown = await resp.json();
  if (isPointerShape(parsed)) {
    validatePointer(parsed, opts.id);
    return loadSafetyPolicy({
      url: parsed.url,
      hash: parsed.hash,
      cache: opts.cache,
      signal: opts.signal,
      fetchImpl: opts.fetchImpl,
      cacheKey: `well-known:${opts.origin}#${opts.id}#${parsed.hash}`,
    });
  }
  validateSafetyPolicy(parsed);
  if (parsed.id !== opts.id) {
    throw new SafetyPolicyDiscoveryError(
      `Inline descriptor id ${JSON.stringify(parsed.id)} does not match requested id ${JSON.stringify(opts.id)}`,
    );
  }
  return parsed;
}

/**
 * Tokenizer map loading + caching.
 *
 * Loads a JSON map from a URL, optionally verifies it against a SHA-256 hash
 * (the form `READY` frames declare), and stores it in a pluggable cache. Maps
 * are immutable once published, so cache hits are always valid.
 *
 * The default cache is in-memory. Browsers can wrap the Cache API; Node can
 * back it with the filesystem; edge runtimes can use KV.
 */
import type { MapCache, TokenizerMap } from './types.js';

// ── Pluggable cache (default: in-memory) ──────────────────────────────────────

export class MemoryMapCache implements MapCache {
  private store = new Map<string, TokenizerMap>();
  async get(key: string): Promise<TokenizerMap | undefined> {
    return this.store.get(key);
  }
  async set(key: string, map: TokenizerMap): Promise<void> {
    this.store.set(key, map);
  }
}

const defaultCache: MapCache = new MemoryMapCache();

// ── Validation ────────────────────────────────────────────────────────────────
//
// Light shape check — we don't pull a full JSON-Schema validator into the wire
// path. The contract is small enough that a hand-written check is honest about
// what we actually require.

export class TokenizerMapValidationError extends Error {
  constructor(message: string) {
    super(`TokenizerMap validation failed: ${message}`);
    this.name = 'TokenizerMapValidationError';
  }
}

export function validateMap(value: unknown): asserts value is TokenizerMap {
  if (typeof value !== 'object' || value === null) {
    throw new TokenizerMapValidationError('not an object');
  }
  const m = value as Record<string, unknown>;
  if (typeof m.id !== 'string') throw new TokenizerMapValidationError('id must be a string');
  if (typeof m.version !== 'string')
    throw new TokenizerMapValidationError('version must be a string');
  if (typeof m.vocab_size !== 'number' || m.vocab_size < 1)
    throw new TokenizerMapValidationError('vocab_size must be a positive integer');
  // v2 maps have `vocab`; v1 maps have `tokens`. At least one is required.
  const hasVocab = typeof m.vocab === 'object' && m.vocab !== null;
  const hasTokens = typeof m.tokens === 'object' && m.tokens !== null;
  if (!hasVocab && !hasTokens) {
    throw new TokenizerMapValidationError('one of `vocab` (v2) or `tokens` (v1) is required');
  }
  if (m.encoder !== undefined && m.encoder !== 'byte_level' && m.encoder !== 'metaspace') {
    throw new TokenizerMapValidationError(
      `encoder must be "byte_level" or "metaspace" if present, got ${JSON.stringify(m.encoder)}`,
    );
  }
  if (m.merges !== undefined && !Array.isArray(m.merges)) {
    throw new TokenizerMapValidationError('merges must be an array of strings');
  }
  if (
    m.byte_fallback_start !== undefined &&
    (typeof m.byte_fallback_start !== 'number' || m.byte_fallback_start < 0)
  ) {
    throw new TokenizerMapValidationError('byte_fallback_start must be a non-negative integer');
  }
  if (
    m.byte_fallback_end !== undefined &&
    (typeof m.byte_fallback_end !== 'number' || m.byte_fallback_end < 0)
  ) {
    throw new TokenizerMapValidationError('byte_fallback_end must be a non-negative integer');
  }
  if (
    (m.byte_fallback_start === undefined) !==
    (m.byte_fallback_end === undefined)
  ) {
    throw new TokenizerMapValidationError(
      'byte_fallback_start and byte_fallback_end must both be set or both omitted'
    );
  }
}

// ── Hashing (SubtleCrypto — works in browser, Node 18+, Cloudflare, Deno) ─────

export class TokenizerMapHashMismatchError extends Error {
  constructor(expected: string, actual: string) {
    super(`TokenizerMap hash mismatch.\n  expected: ${expected}\n  actual:   ${actual}`);
    this.name = 'TokenizerMapHashMismatchError';
  }
}

async function sha256Hex(bytes: Uint8Array): Promise<string> {
  // globalThis.crypto.subtle is available everywhere we target.
  const subtle = (globalThis as { crypto?: { subtle?: SubtleCrypto } }).crypto?.subtle;
  if (!subtle) {
    throw new Error(
      '@codecai/web requires a SubtleCrypto implementation (Web Crypto API). ' +
        'Available in browsers, Node 18+, Cloudflare Workers, Deno.'
    );
  }
  const digest = await subtle.digest('SHA-256', bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer);
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/** Parse a hash string in the form `sha256:<hex>` or just `<hex>`. */
function parseHash(hash: string): string {
  const colon = hash.indexOf(':');
  if (colon === -1) return hash.toLowerCase();
  const algo = hash.slice(0, colon).toLowerCase();
  if (algo !== 'sha256') {
    throw new Error(`Unsupported hash algorithm: ${algo} (only sha256 supported)`);
  }
  return hash.slice(colon + 1).toLowerCase();
}

// ── Loader ────────────────────────────────────────────────────────────────────

export interface LoadOptions {
  /** URL to fetch the map from. */
  url: string;
  /**
   * Optional SHA-256 hex digest to verify the fetched map against.
   * Accepts `sha256:<hex>` or bare `<hex>`. If omitted, no verification.
   */
  hash?: string;
  /** Pluggable cache. Defaults to a process-wide in-memory cache. */
  cache?: MapCache;
  /** AbortSignal for the fetch. */
  signal?: AbortSignal;
  /** Custom fetch implementation. Defaults to `globalThis.fetch`. */
  fetchImpl?: typeof fetch;
  /**
   * Cache key. Defaults to the URL plus hash. Override if you want to share
   * cached maps across URLs (e.g. CDN failover).
   */
  cacheKey?: string;
}

/**
 * Fetch, verify, and cache a tokenizer map. Cache hits skip the network.
 *
 *   const map = await loadMap({
 *     url: 'https://maps.codec.ai/llama-3.1-8b.json',
 *     hash: 'sha256:abcd…'
 *   });
 */
export async function loadMap(opts: LoadOptions): Promise<TokenizerMap> {
  const cache = opts.cache ?? defaultCache;
  const cacheKey = opts.cacheKey ?? `${opts.url}#${opts.hash ?? ''}`;

  const cached = await cache.get(cacheKey);
  if (cached) return cached;

  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error(
      '@codec/web: no global fetch available. Pass `fetchImpl` or upgrade to Node 18+.'
    );
  }

  const resp = await fetchImpl(opts.url, { signal: opts.signal });
  if (!resp.ok) {
    throw new Error(`Failed to fetch tokenizer map from ${opts.url}: HTTP ${resp.status}`);
  }
  const bytes = new Uint8Array(await resp.arrayBuffer());

  if (opts.hash) {
    const expected = parseHash(opts.hash);
    const actual = await sha256Hex(bytes);
    if (expected !== actual) throw new TokenizerMapHashMismatchError(expected, actual);
  }

  const text = new TextDecoder().decode(bytes);
  const parsed: unknown = JSON.parse(text);
  validateMap(parsed);

  await cache.set(cacheKey, parsed);
  return parsed;
}

/** Construct a TokenizerMap directly from an object (useful for tests, embeds). */
export function makeMap(spec: TokenizerMap): TokenizerMap {
  validateMap(spec);
  return spec;
}

/**
 * Map discovery via the `.well-known/codec/` convention.
 *
 * Given an origin and a map ID, fetch the per-map document at
 *
 *     <origin>/.well-known/codec/maps/<id>.json
 *
 * and return a verified TokenizerMap. The document is one of two shapes
 * (the loader auto-detects):
 *
 *   - Pointer: `{ id, url, hash }` referencing the actual map on a CDN.
 *   - Inline:  the full TokenizerMap directly.
 *
 * See `spec/WELL_KNOWN_DISCOVERY.md` for the full convention.
 */
import type { MapCache, TokenizerMap } from './types.js';
import { loadMap, validateMap } from './map.js';

/** Fixed base path under which Codec discovery documents live. */
export const WELL_KNOWN_BASE = '/.well-known/codec';

/** Per-map document URL for an origin + id. */
export function wellKnownMapUrl(origin: string, id: string): string {
  return `${stripTrailingSlash(origin)}${WELL_KNOWN_BASE}/maps/${encodeMapId(id)}.json`;
}

/** Index document URL for an origin. */
export function wellKnownIndexUrl(origin: string): string {
  return `${stripTrailingSlash(origin)}${WELL_KNOWN_BASE}/index.json`;
}

function stripTrailingSlash(s: string): string {
  return s.endsWith('/') ? s.slice(0, -1) : s;
}

/**
 * IDs are lowercase ASCII matching `[a-z0-9._/-]+`. Slashes are preserved as
 * URL path separators. Anything outside that set is rejected — discovery is
 * a public, cacheable surface and we don't want exotic encodings creating
 * cache-poisoning ambiguity.
 */
function encodeMapId(id: string): string {
  if (!/^[a-z0-9._/-]+$/.test(id)) {
    throw new MapDiscoveryError(
      `Invalid map id ${JSON.stringify(id)}: must match [a-z0-9._/-]+`,
    );
  }
  if (id.includes('..') || id.startsWith('/') || id.endsWith('/')) {
    throw new MapDiscoveryError(
      `Invalid map id ${JSON.stringify(id)}: path traversal or empty segment`,
    );
  }
  return id;
}

// ── Pointer + index document shapes ───────────────────────────────────────────

/** Pointer document: small file at `.well-known/codec/maps/<id>.json` (Form A). */
export interface MapPointer {
  readonly id: string;
  readonly url: string;
  readonly hash: string;
  readonly published_at?: string;
}

/** Index document: enumerates every map an origin publishes. */
export interface MapIndex {
  readonly codec_version: string;
  readonly maps: ReadonlyArray<MapPointer>;
}

// ── Errors ────────────────────────────────────────────────────────────────────

export class MapDiscoveryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MapDiscoveryError';
  }
}

export class MapDiscoveryNotFoundError extends MapDiscoveryError {
  constructor(url: string, status: number) {
    super(`No map document at ${url} (HTTP ${status})`);
    this.name = 'MapDiscoveryNotFoundError';
  }
}

// ── Detection: pointer vs. inline map ─────────────────────────────────────────

function isPointerShape(obj: unknown): obj is MapPointer {
  if (typeof obj !== 'object' || obj === null) return false;
  const o = obj as Record<string, unknown>;
  return (
    typeof o.id === 'string' &&
    typeof o.url === 'string' &&
    typeof o.hash === 'string' &&
    // Inline maps always carry vocab/tokens; pointers never do.
    o.vocab === undefined &&
    o.tokens === undefined
  );
}

function validatePointer(obj: MapPointer, expectedId: string): void {
  if (obj.id !== expectedId) {
    throw new MapDiscoveryError(
      `Pointer id ${JSON.stringify(obj.id)} does not match requested id ${JSON.stringify(expectedId)}`,
    );
  }
  let parsed: URL;
  try {
    parsed = new URL(obj.url);
  } catch {
    throw new MapDiscoveryError(`Pointer url is not a valid URL: ${obj.url}`);
  }
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new MapDiscoveryError(
      `Pointer url must be http(s): got ${parsed.protocol}`,
    );
  }
  if (!/^sha256:[0-9a-f]{64}$/i.test(obj.hash)) {
    throw new MapDiscoveryError(
      `Pointer hash must be sha256:<64 hex chars>: got ${obj.hash}`,
    );
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

export interface DiscoverMapOptions {
  /** HTTPS origin of the maintainer publishing the map (e.g. `https://qwen.io`). */
  origin: string;

  /** Codec map ID (e.g. `qwen/qwen2`). */
  id: string;

  /** Pluggable cache, shared with `loadMap`. */
  cache?: MapCache;

  /** AbortSignal forwarded to all underlying fetches. */
  signal?: AbortSignal;

  /** Custom fetch implementation. Defaults to `globalThis.fetch`. */
  fetchImpl?: typeof fetch;
}

/**
 * Resolve a tokenizer map via the `.well-known/codec/` convention.
 *
 * Fetches `<origin>/.well-known/codec/maps/<id>.json`, then either follows
 * the pointer's `url` + verifies its `hash` (Form A), or validates and
 * returns the inline map directly (Form B).
 *
 *   const map = await discoverMap({
 *     origin: 'https://qwen.io',
 *     id: 'qwen/qwen2',
 *   });
 *
 * Throws `MapDiscoveryNotFoundError` for 404, `MapDiscoveryError` for
 * malformed pointers, and `TokenizerMapHashMismatchError` if the CDN bytes
 * don't match the pointer hash.
 */
export async function discoverMap(opts: DiscoverMapOptions): Promise<TokenizerMap> {
  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new MapDiscoveryError(
      '@codecai/web: no global fetch available. Pass `fetchImpl` or upgrade to Node 18+.',
    );
  }

  const url = wellKnownMapUrl(opts.origin, opts.id);
  const resp = await fetchImpl(url, { signal: opts.signal });
  if (resp.status === 404) {
    throw new MapDiscoveryNotFoundError(url, resp.status);
  }
  if (!resp.ok) {
    throw new MapDiscoveryError(
      `Failed to fetch ${url}: HTTP ${resp.status}`,
    );
  }

  const parsed: unknown = await resp.json();
  if (isPointerShape(parsed)) {
    validatePointer(parsed, opts.id);
    return loadMap({
      url: parsed.url,
      hash: parsed.hash,
      cache: opts.cache,
      signal: opts.signal,
      fetchImpl: opts.fetchImpl,
      cacheKey: `well-known:${opts.origin}#${opts.id}#${parsed.hash}`,
    });
  }

  // Otherwise: inline TokenizerMap. Validate, sanity-check id, return.
  validateMap(parsed);
  if (parsed.id !== opts.id) {
    throw new MapDiscoveryError(
      `Inline map id ${JSON.stringify(parsed.id)} does not match requested id ${JSON.stringify(opts.id)}`,
    );
  }
  return parsed;
}

export interface DiscoverIndexOptions {
  origin: string;
  signal?: AbortSignal;
  fetchImpl?: typeof fetch;
}

/**
 * Fetch the optional `.well-known/codec/index.json` directory document for
 * an origin. Returns the parsed index; throws `MapDiscoveryNotFoundError`
 * if the origin doesn't publish one.
 */
export async function discoverIndex(opts: DiscoverIndexOptions): Promise<MapIndex> {
  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new MapDiscoveryError(
      '@codecai/web: no global fetch available. Pass `fetchImpl` or upgrade to Node 18+.',
    );
  }

  const url = wellKnownIndexUrl(opts.origin);
  const resp = await fetchImpl(url, { signal: opts.signal });
  if (resp.status === 404) {
    throw new MapDiscoveryNotFoundError(url, resp.status);
  }
  if (!resp.ok) {
    throw new MapDiscoveryError(`Failed to fetch ${url}: HTTP ${resp.status}`);
  }

  const parsed: unknown = await resp.json();
  if (
    typeof parsed !== 'object' ||
    parsed === null ||
    typeof (parsed as MapIndex).codec_version !== 'string' ||
    !Array.isArray((parsed as MapIndex).maps)
  ) {
    throw new MapDiscoveryError(`Index at ${url} is not a valid MapIndex document`);
  }
  for (const entry of (parsed as MapIndex).maps) {
    if (!isPointerShape(entry)) {
      throw new MapDiscoveryError(
        `Index entry at ${url} is missing required pointer fields`,
      );
    }
  }
  return parsed as MapIndex;
}

/**
 * Detokenizer — IDs → text. Invoked only when a human is going to read the
 * output. Agent-to-agent calls skip this layer entirely.
 *
 * Three correctness concerns it has to get right:
 *
 *   1. Per-token decoding. The way to recover text from a token's vocab key
 *      depends on the map's `encoder` field:
 *        byte_level — each vocab key is a string of GPT-2-encoded bytes
 *                     (Llama-3, Qwen, Phi-3 …); reverse the byte table.
 *        metaspace  — each vocab key is a ▁-prefixed string (Llama-2,
 *                     Mistral-v3, Mixtral, Gemma); replace ▁ with space.
 *        identity   — vocab keys are already decoded text (test fixtures,
 *                     v1 schema maps).
 *
 *   2. Byte-fallback range. SentencePiece-style maps reserve IDs for raw
 *      bytes 0x00–0xFF. These tokens are decoded as single bytes and
 *      accumulated until they form a valid UTF-8 sequence.
 *
 *   3. Partial multi-byte sequences across frame boundaries. A frame
 *      boundary is never a valid rendering boundary for a partial emoji or
 *      multi-byte character. The detokenizer buffers partial bytes between
 *      calls (when `partial: true`) and flushes them when complete.
 */
import { decodeByteLevelToken, METASPACE } from './encoder.js';
import type { TokenizerMap } from './types.js';

export interface DetokenizeOptions {
  /**
   * If true, this is not the final chunk — buffer any trailing partial
   * UTF-8 sequence rather than emitting replacement characters. Set to
   * `false` (or omit) on the last chunk so the buffer flushes.
   */
  partial?: boolean;
  /** If true, render special tokens (e.g. `<|eos|>`) as text. Default: false. */
  renderSpecial?: boolean;
}

export class Detokenizer {
  private readonly map: TokenizerMap;
  private readonly specialIds: Set<number>;
  private readonly fallbackStart: number;
  private readonly fallbackEnd: number;

  /**
   * id → bytes for byte_level maps (every vocab token is a byte sequence),
   * or null for non-byte_level maps where lookup goes through `idToText`.
   */
  private readonly idToBytes: Map<number, Uint8Array> | null;

  /** id → already-decoded text. Used for metaspace and identity encoders. */
  private readonly idToText: Map<number, string> | null;

  private byteBuffer: number[] = [];

  constructor(map: TokenizerMap) {
    this.map = map;
    this.specialIds = new Set(Object.values(map.special_tokens ?? {}));
    this.fallbackStart = map.byte_fallback_start ?? -1;
    this.fallbackEnd = map.byte_fallback_end ?? -2;

    if (map.encoder === 'byte_level') {
      this.idToBytes = buildByteLevelTable(map);
      this.idToText = null;
    } else {
      this.idToBytes = null;
      this.idToText = buildTextTable(map);
    }
  }

  /**
   * Render a chunk of IDs to text. Stateful across calls — partial
   * multi-byte sequences carry over until completed by a later chunk.
   *
   *   const detok = new Detokenizer(map);
   *   for await (const frame of decodeStream(stream)) {
   *     out += detok.render(frame.ids, { partial: !frame.done });
   *   }
   */
  render(ids: readonly number[], opts: DetokenizeOptions = {}): string {
    const partial = opts.partial ?? false;
    const renderSpecial = opts.renderSpecial ?? false;
    let out = '';

    for (const id of ids) {
      // Byte-fallback range: SentencePiece maps reserve a contiguous block
      // of IDs for raw bytes 0x00–0xFF.
      if (id >= this.fallbackStart && id <= this.fallbackEnd) {
        this.byteBuffer.push(id - this.fallbackStart);
        const flushed = this.tryFlushBytes();
        if (flushed) out += flushed;
        continue;
      }

      // byte_level path — every vocab token is itself a byte sequence,
      // so we route all token bytes through the same UTF-8 buffer logic.
      if (this.idToBytes) {
        if (this.specialIds.has(id) && !renderSpecial) {
          // Specials still live in the vocab but should not surface as text.
          // Flush any pending bytes first to avoid splitting a multi-byte char.
          if (this.byteBuffer.length > 0) out += this.flushBytesForce();
          continue;
        }
        const bytes = this.idToBytes.get(id);
        if (bytes === undefined) {
          if (this.byteBuffer.length > 0) out += this.flushBytesForce();
          out += '�';
          continue;
        }
        for (let i = 0; i < bytes.length; i++) this.byteBuffer.push(bytes[i]!);
        const flushed = this.tryFlushAllBytes();
        if (flushed) out += flushed;
        continue;
      }

      // metaspace / identity path — token text is rendered directly.
      // Flush any pending byte-fallback bytes first.
      if (this.byteBuffer.length > 0) out += this.flushBytesForce();

      if (this.specialIds.has(id) && !renderSpecial) continue;

      const text = this.idToText!.get(id);
      if (text !== undefined) {
        out += text;
      } else {
        out += '�';
      }
    }

    if (!partial && this.byteBuffer.length > 0) {
      out += this.flushBytesForce();
    }
    return out;
  }

  /** Reset internal state — call between conversations / requests. */
  reset(): void {
    this.byteBuffer = [];
  }

  /** Decode whatever complete UTF-8 prefix sits in the buffer; keep the rest. */
  private tryFlushAllBytes(): string {
    let out = '';
    while (this.byteBuffer.length > 0) {
      const needed = utf8SequenceLength(this.byteBuffer[0]!);
      if (needed === 0) {
        this.byteBuffer.shift();
        out += '�';
        continue;
      }
      if (this.byteBuffer.length < needed) break;
      const bytes = this.byteBuffer.splice(0, needed);
      try {
        out += new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(bytes));
      } catch {
        out += '�';
      }
    }
    return out;
  }

  /** Single-sequence flush — used by the byte-fallback range path. */
  private tryFlushBytes(): string | null {
    if (this.byteBuffer.length === 0) return null;
    const needed = utf8SequenceLength(this.byteBuffer[0]!);
    if (needed === 0) {
      this.byteBuffer.shift();
      return '�';
    }
    if (this.byteBuffer.length < needed) return null;
    const bytes = this.byteBuffer.splice(0, needed);
    try {
      return new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(bytes));
    } catch {
      return '�';
    }
  }

  /** Flush whatever's in the buffer, replacing invalid bytes with U+FFFD. */
  private flushBytesForce(): string {
    if (this.byteBuffer.length === 0) return '';
    const bytes = new Uint8Array(this.byteBuffer);
    this.byteBuffer = [];
    return new TextDecoder('utf-8').decode(bytes);
  }
}

/**
 * Number of bytes a UTF-8 sequence starting with `b` requires, or 0 if `b`
 * is not a valid leading byte.
 */
function utf8SequenceLength(b: number): number {
  if ((b & 0x80) === 0x00) return 1; // 0xxxxxxx
  if ((b & 0xe0) === 0xc0) return 2; // 110xxxxx
  if ((b & 0xf0) === 0xe0) return 3; // 1110xxxx
  if ((b & 0xf8) === 0xf0) return 4; // 11110xxx
  return 0;
}

/** Build id → bytes table for byte_level maps. */
function buildByteLevelTable(map: TokenizerMap): Map<number, Uint8Array> {
  const out = new Map<number, Uint8Array>();
  if (!map.vocab) return out;
  for (const [token, id] of Object.entries(map.vocab)) {
    out.set(id, decodeByteLevelToken(token));
  }
  return out;
}

/**
 * Build id → text table for metaspace and identity (incl. v1) maps.
 * - metaspace: replace ▁ with space.
 * - identity / v1: token text is already decoded.
 */
function buildTextTable(map: TokenizerMap): Map<number, string> {
  const out = new Map<number, string>();
  const isMetaspace = map.encoder === 'metaspace';

  // v2 maps: { raw_token: id }
  if (map.vocab) {
    for (const [token, id] of Object.entries(map.vocab)) {
      // SentencePiece byte-fallback tokens (<0x00>…<0xFF>) live in vocab
      // but are handled by the byte_fallback range path — skip here.
      if (/^<0x[0-9A-Fa-f]{2}>$/.test(token)) continue;
      const text = isMetaspace ? token.replace(/▁/g, ' ') : token;
      out.set(id, text);
    }
  }

  // v1 maps: { id_string: decoded_text }
  if (map.tokens) {
    for (const [idStr, text] of Object.entries(map.tokens)) {
      out.set(Number(idStr), text);
    }
  }

  return out;
}

/** Convenience: detokenize a complete sequence in one shot. */
export function detokenize(
  map: TokenizerMap,
  ids: readonly number[],
  opts?: Omit<DetokenizeOptions, 'partial'>,
): string {
  const d = new Detokenizer(map);
  return d.render(ids, { ...opts, partial: false });
}

/**
 * Tokenizer — text → IDs. The edge-side encoder.
 *
 * Two implementations ship in this package:
 *
 *   - `BPETokenizer` (in `./bpe.ts`) — exact BPE encoding for byte_level and
 *     metaspace maps. Use this with any v2 map that has `merges` (every map
 *     fetched from `codec-maps` for a real model).
 *
 *   - `LongestMatchTokenizer` (this file) — vocab-only longest-prefix-match.
 *     Correct for canonical-IR / synthetic maps without merges (test
 *     fixtures, simple/closed vocabs).
 *
 * Both implement the `Tokenizer` interface so users can swap freely.
 *
 * The `tokenize()` convenience function picks the right implementation based
 * on the map's contents — if `merges` is present, BPE; otherwise longest match.
 */
import { BPETokenizer } from './bpe.js';
import type { Tokenizer, TokenizerMap } from './types.js';

/**
 * Longest-prefix-match tokenizer. Walks the input left-to-right, at each
 * position emitting the ID of the longest vocab fragment that matches.
 *
 * Suitable for canonical-IR maps and test fixtures. Not BPE-correct for
 * real model vocabs — use `BPETokenizer` for those.
 */
export class LongestMatchTokenizer implements Tokenizer {
  readonly id: string;

  private readonly fragmentToId = new Map<string, number>();
  private readonly maxFragmentLength: number;
  private readonly specialFragmentToId = new Map<string, number>();

  constructor(map: TokenizerMap) {
    this.id = map.id;

    let maxLen = 1;
    // v2 maps: vocab is { fragment: id }
    if (map.vocab) {
      for (const [fragment, id] of Object.entries(map.vocab)) {
        if (!fragment) continue;
        this.fragmentToId.set(fragment, id);
        if (fragment.length > maxLen) maxLen = fragment.length;
      }
    }
    // v1 maps: tokens is { id_string: fragment }
    if (map.tokens) {
      for (const [idStr, fragment] of Object.entries(map.tokens)) {
        if (!fragment) continue;
        const id = Number(idStr);
        this.fragmentToId.set(fragment, id);
        if (fragment.length > maxLen) maxLen = fragment.length;
      }
    }
    this.maxFragmentLength = maxLen;

    for (const [name, id] of Object.entries(map.special_tokens ?? {})) {
      // Accept both raw form (`<|eos|>`) and short form (`eos`).
      this.specialFragmentToId.set(name, id);
      if (!name.startsWith('<')) {
        this.specialFragmentToId.set(`<|${name}|>`, id);
      }
    }
  }

  encode(text: string): number[] {
    const out: number[] = [];
    let pos = 0;
    const n = text.length;

    while (pos < n) {
      // Special tokens win when present.
      let consumed = false;
      for (const [frag, id] of this.specialFragmentToId) {
        if (text.startsWith(frag, pos)) {
          out.push(id);
          pos += frag.length;
          consumed = true;
          break;
        }
      }
      if (consumed) continue;

      const remaining = n - pos;
      const tryUpTo = Math.min(this.maxFragmentLength, remaining);
      let matchedId = -1;
      let matchedLen = 0;
      for (let len = tryUpTo; len >= 1; len--) {
        const candidate = text.slice(pos, pos + len);
        const id = this.fragmentToId.get(candidate);
        if (id !== undefined) {
          matchedId = id;
          matchedLen = len;
          break;
        }
      }

      if (matchedId === -1) {
        out.push(0); // UNK by convention
        pos += 1;
      } else {
        out.push(matchedId);
        pos += matchedLen;
      }
    }
    return out;
  }
}

/**
 * Build the right tokenizer for the map. Uses `BPETokenizer` when the map
 * carries BPE data (vocab + merges + encoder); otherwise falls back to
 * `LongestMatchTokenizer`, which works on any vocab-bearing map.
 */
export function pickTokenizer(map: TokenizerMap): Tokenizer {
  if (BPETokenizer.supports(map)) return new BPETokenizer(map);
  return new LongestMatchTokenizer(map);
}

/** One-shot encode using `pickTokenizer`. */
export function tokenize(map: TokenizerMap, text: string): number[] {
  return pickTokenizer(map).encode(text);
}

// Re-export the Tokenizer interface for external use.
export type { Tokenizer } from './types.js';

/**
 * Translator — cross-vocab token-stream pipe.
 *
 * Take Agent A's token IDs in vocab V_A, produce Agent B's token IDs in
 * vocab V_B, with no text ever leaving the process. Internally:
 *
 *   ids_A → Detokenizer(V_A) → utf8 → BPETokenizer(V_B) → ids_B
 *
 * The text intermediate is purely local; agent-to-agent traffic still
 * carries only token IDs on the wire. This is the scenario the Codec
 * spec calls a "cross-vocab agent handoff" — when two models with
 * different vocabularies are chained without a human reader in between.
 *
 * Use cases:
 *   - Pipe Llama-3's output into Qwen-2's input (different BPE vocabs)
 *   - Drop a Mistral-v3 step into a Llama-3 chain (different families)
 *   - Run a router / orchestrator that fans out to heterogeneous models
 *
 * Streaming caveat: BPE merges depend on context, so re-tokenizing partial
 * words mid-stream produces different IDs than re-tokenizing the complete
 * word. The Translator buffers text until a safe boundary (whitespace)
 * before flushing through BPE. Call `translate(ids, { partial: true })`
 * for incoming chunks and `translate(ids)` (or `partial: false`) for the
 * final chunk to flush any trailing word.
 */
import { Detokenizer } from './detokenize.js';
import { pickTokenizer } from './tokenize.js';
import type { Tokenizer, TokenizerMap } from './types.js';

export interface TranslateOptions {
  /**
   * If true, this is not the final chunk — buffer any trailing partial
   * word rather than flushing it through BPE prematurely. Set to `false`
   * (or omit) on the last chunk so the buffer drains.
   */
  partial?: boolean;
}

export class Translator {
  readonly fromId: string;
  readonly toId: string;
  private readonly fromDetok: Detokenizer;
  private readonly toTok: Tokenizer;
  private textBuffer: string = '';

  constructor(fromMap: TokenizerMap, toMap: TokenizerMap) {
    this.fromId = fromMap.id;
    this.toId = toMap.id;
    this.fromDetok = new Detokenizer(fromMap);
    this.toTok = pickTokenizer(toMap);
  }

  /**
   * Translate a chunk of source-vocab IDs to target-vocab IDs.
   * Stateful across calls — partial words are buffered when
   * `opts.partial` is true.
   */
  translate(ids: readonly number[], opts: TranslateOptions = {}): number[] {
    const partial = opts.partial ?? false;
    // Render through V_A's detokenizer with the same partial flag — this
    // already handles partial UTF-8 byte sequences across token boundaries.
    const text = this.fromDetok.render(ids, { partial });
    if (text.length > 0) this.textBuffer += text;

    if (!partial) {
      // Final chunk — flush everything.
      const out = this.toTok.encode(this.textBuffer);
      this.textBuffer = '';
      return out;
    }

    // Streaming chunk — find the last safe boundary and flush before it.
    // Pre-tokenizers (both byte_level and metaspace) split at whitespace,
    // so re-encoding text up to and including the last whitespace yields
    // the same IDs as re-encoding the complete word later.
    const safe = this.findLastSafeBoundary(this.textBuffer);
    if (safe <= 0) return [];

    const toEncode = this.textBuffer.slice(0, safe);
    this.textBuffer = this.textBuffer.slice(safe);
    return this.toTok.encode(toEncode);
  }

  /**
   * Reset internal state — call between conversations.
   */
  reset(): void {
    this.fromDetok.reset();
    this.textBuffer = '';
  }

  /**
   * Convenience: end-of-stream flush. Equivalent to
   * `translate([], { partial: false })` but more readable.
   */
  finish(): number[] {
    return this.translate([], { partial: false });
  }

  /**
   * Find the last index that's safe to cut at. We prefer the position
   * just after the last whitespace character, since BPE pre-tokenizers
   * always split there. If the buffer has no whitespace, return 0
   * (nothing safe to flush — keep buffering).
   */
  private findLastSafeBoundary(s: string): number {
    // Iterate codepoints from the end. Stop at the last whitespace and
    // return the position immediately after it. The trailing word stays
    // buffered until the next whitespace arrives.
    for (let i = s.length - 1; i >= 0; i--) {
      const c = s.charCodeAt(i);
      // ASCII whitespace + common Unicode whitespace block — covers the
      // pre-tokenizer regexes used by Llama-3, Qwen, Phi-3, Mistral, etc.
      if (c === 0x20 || c === 0x09 || c === 0x0A || c === 0x0D ||
          c === 0x0B || c === 0x0C || c === 0x00A0 || c === 0x2028 ||
          c === 0x2029 || c === 0x3000) {
        return i + 1;
      }
    }
    return 0;
  }
}

/**
 * Convenience: one-shot translate without keeping a Translator instance.
 * Useful for non-streaming cases where you have all the IDs up front.
 */
export function translate(
  fromMap: TokenizerMap,
  toMap: TokenizerMap,
  ids: readonly number[],
): number[] {
  return new Translator(fromMap, toMap).translate(ids);
}

/**
 * Build a static V_A → V_B[] translation table by feeding each V_A token's
 * decoded text through V_B's tokenizer. Useful for analysis (vocab overlap,
 * cost estimation) and for fast lookups when context-free translation is
 * acceptable.
 *
 * Limitations: this is context-free — token boundaries don't align across
 * vocabs, and BPE merges depend on context. The single-shot result
 * `staticTranslationTable(A, B)[id_A]` may differ from what `translate`
 * produces when the same `id_A` appears mid-sentence. For exact streaming
 * translation, use the `Translator` class.
 */
export function staticTranslationTable(
  fromMap: TokenizerMap,
  toMap: TokenizerMap,
): Map<number, number[]> {
  const detok = new Detokenizer(fromMap);
  const tok = pickTokenizer(toMap);
  const out = new Map<number, number[]>();

  // Walk the source vocab. Skip special tokens — they have no semantic
  // text representation that translates meaningfully.
  const specialIds = new Set(Object.values(fromMap.special_tokens ?? {}));
  const vocab = fromMap.vocab ?? {};
  for (const [, id] of Object.entries(vocab)) {
    if (specialIds.has(id)) continue;
    const text = detok.render([id]);
    if (text.length === 0) continue;
    out.set(id, tok.encode(text));
    detok.reset();
  }

  // v1 maps: also walk `tokens`
  const tokens = fromMap.tokens ?? {};
  for (const idStr of Object.keys(tokens)) {
    const id = Number(idStr);
    if (Number.isNaN(id) || specialIds.has(id) || out.has(id)) continue;
    const text = detok.render([id]);
    if (text.length === 0) continue;
    out.set(id, tok.encode(text));
    detok.reset();
  }

  return out;
}

/**
 * ToolWatcher — detect tool-call regions in a token-ID stream without
 * decoding.
 *
 * Mirrors the C `codec_tool_watcher` API. Most chat-tuned models delimit
 * tool calls with single-token specials (`<tool_call>` / `</tool_call>`
 * for Qwen 2.5+, `<|python_tag|>` / `<|eom_id|>` for Llama 3.1+, etc.).
 * Detecting *that* a tool call happened is therefore a uint32 compare
 * in the hot loop — no detokenization, no string allocation.
 *
 * The watcher emits two kinds of events per `feed()` call:
 *   - `passthrough`: IDs outside any watched region (route as-is to the
 *     next agent).
 *   - `region`: a complete start..end region with markers excluded
 *     (decode only when you actually need the JSON arguments).
 *
 * State survives across `feed()` calls: a region split between network
 * frames buffers internally until the end marker arrives.
 *
 * Performance: the hot loop is a single uint32 compare against two
 * cached IDs plus an occasional push into a number[]. Roughly two
 * orders of magnitude faster than a detokenize over the same stream.
 */
import type { TokenizerMap } from './types.js';

export type WatcherEvent =
  | { readonly kind: 'passthrough'; readonly ids: ReadonlyArray<number> }
  | { readonly kind: 'region';      readonly ids: ReadonlyArray<number> };

export class ToolWatcherError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ToolWatcherError';
  }
}

export class ToolWatcher {
  readonly startId: number;
  readonly endId:   number;
  readonly startName: string;
  readonly endName:   string;

  private _inside = false;
  /* Region buffer survives across feeds — markers excluded. */
  private region: number[] = [];

  constructor(map: TokenizerMap, startName: string, endName: string) {
    const specials = map.special_tokens ?? {};
    const startId = specials[startName];
    const endId   = specials[endName];
    if (typeof startId !== 'number') {
      throw new ToolWatcherError(
        `special token "${startName}" not in map.special_tokens`);
    }
    if (typeof endId !== 'number') {
      throw new ToolWatcherError(
        `special token "${endName}" not in map.special_tokens`);
    }
    this.startId   = startId;
    this.endId     = endId;
    this.startName = startName;
    this.endName   = endName;
  }

  /** True when a region is currently open (start seen, end not yet). */
  get inside(): boolean { return this._inside; }

  /**
   * Reset state — drops any in-flight region buffer. Call between
   * conversations so a leftover unclosed region from session N doesn't
   * spill into session N+1.
   */
  reset(): void {
    this._inside = false;
    this.region = [];
  }

  /**
   * Feed a chunk of token IDs and receive a flat array of events. The
   * returned `ids` arrays:
   *   - For `passthrough`: a slice of the input, valid for as long as
   *     the caller's input stays alive.
   *   - For `region`: a fresh array owned by the caller, valid forever
   *     (we hand out a copy of the buffered region and reset).
   */
  feed(input: ReadonlyArray<number> | Uint32Array): WatcherEvent[] {
    const events: WatcherEvent[] = [];
    const n = input.length;
    let ptStart = 0;

    /* Single-pass scan. Identical state machine to the C
     * implementation — keep them in sync if you change one. */
    for (let i = 0; i < n; i++) {
      const id = input[i]!;

      if (!this._inside) {
        if (id === this.startId) {
          if (i > ptStart) {
            events.push({ kind: 'passthrough', ids: sliceIds(input, ptStart, i) });
          }
          this._inside = true;
          this.region = [];
          /* ptStart is re-anchored when the region closes. */
        }
        /* else: token continues the passthrough run; no action. */
      } else {
        if (id === this.endId) {
          /* Region complete — emit a fresh array (caller-owned, doesn't
           * alias our buffer the way the C version does). */
          events.push({ kind: 'region', ids: this.region });
          this.region = [];
          this._inside = false;
          ptStart = i + 1;
        } else if (id === this.startId) {
          /* Nested start; ignore. Most models don't nest these markers,
           * and treating an inner start as a new region would silently
           * drop the outer content. */
        } else {
          this.region.push(id);
        }
      }
    }

    /* Trailing passthrough run, if we ended outside a region. */
    if (!this._inside && ptStart < n) {
      events.push({ kind: 'passthrough', ids: sliceIds(input, ptStart, n) });
    }

    return events;
  }
}

function sliceIds(input: ReadonlyArray<number> | Uint32Array,
                  from: number, to: number): number[] {
  /* Always copy out to a plain array so callers don't have to think
   * about whether they got a Uint32Array slice or a number[] slice. */
  const out = new Array<number>(to - from);
  for (let i = 0; i < to - from; i++) out[i] = input[from + i]!;
  return out;
}

/**
 * BPETokenizer — pure JS BPE encoder. Text → token IDs.
 *
 * Required for the bidirectional Codec endpoint: when a human types into a
 * chat box, the client tokenizes locally so input goes over the wire as
 * uint32 IDs (not text), preserving the ~95% wire reduction for both sides.
 *
 * Algorithm (for both byte_level and metaspace BPE):
 *
 *   1. Pre-tokenize. Split input text into pieces.
 *        byte_level: apply the Unicode regex from `pre_tokenizer_pattern`
 *                    (model-specific; e.g. Llama-3 splits on word/whitespace
 *                    boundaries with contraction handling).
 *        metaspace:  split on ASCII whitespace; prefix the first piece (or
 *                    every piece for `prepend_scheme: always`) with ▁.
 *
 *   2. Encode each piece to the vocab's character space.
 *        byte_level: UTF-8 encode the piece, map each byte through the
 *                    GPT-2 byte→unicode table.
 *        metaspace:  text already lives in vocab space — replace spaces
 *                    inside the piece with ▁ and we're done.
 *
 *   3. Apply BPE merges. Start with each codepoint as its own token; greedily
 *      merge the highest-priority pair (lowest merge index) repeatedly until
 *      no rules apply. This matches HuggingFace's reference implementation.
 *
 *   4. Look up final tokens in `vocab`. Tokens not in the vocab are emitted
 *      via byte fallback if available (metaspace), otherwise dropped (this
 *      shouldn't happen for byte_level since every byte is in the vocab).
 *
 * Pure JS, no wasm, no native deps. ~200 lines.
 */
import { encodeByteLevelChars, METASPACE } from './encoder.js';
import { runPreTokProgram, type PreTokProgram } from './pretok-program.js';
import type { Tokenizer, TokenizerMap } from './types.js';

export class BPETokenizer implements Tokenizer {
  readonly id: string;
  private readonly map: TokenizerMap;
  private readonly vocab: ReadonlyMap<string, number>;
  /** "left right" → priority (lower wins). */
  private readonly mergeRanks: ReadonlyMap<string, number>;
  private readonly preTokRegex: RegExp | null;
  private readonly preTokProgram: PreTokProgram | null;
  private readonly encoder: 'byte_level' | 'metaspace';
  private readonly byteFallbackStart: number;
  private readonly cache = new Map<string, number[]>();
  /**
   * Special-token scanner. Built from `map.special_tokens` plus any token in
   * `map.vocab` whose surface form looks like a delimiter (`<|...|>`). HF's
   * reference tokenizer splits input on added/special tokens BEFORE running
   * BPE — emit each match as the atomic vocab ID, BPE the surrounding text.
   * Required for chat templates (`<|im_start|>...<|im_end|>`), tool-call
   * delimiters, FIM markers, etc. to round-trip with HF.
   */
  private readonly specialIds: ReadonlyMap<string, number>;
  private readonly specialRegex: RegExp | null;

  /**
   * Returns true if `map` carries the data BPETokenizer needs (vocab, merges,
   * a supported encoder). When false, callers should fall back to
   * LongestMatchTokenizer — the top-level `tokenize()` helper does this
   * automatically, and `pickTokenizer(map)` returns the right one.
   */
  static supports(map: TokenizerMap): boolean {
    return Boolean(
      map.vocab &&
        map.merges && map.merges.length > 0 &&
        (map.encoder === 'byte_level' || map.encoder === 'metaspace'),
    );
  }

  constructor(map: TokenizerMap) {
    if (!BPETokenizer.supports(map)) {
      throw new Error(
        `BPETokenizer: map "${map.id}" lacks vocab/merges/encoder. ` +
          `Use BPETokenizer.supports(map) to check first, or call ` +
          `tokenize(map, text) which falls back to LongestMatchTokenizer.`,
      );
    }

    // After supports() check above, these are guaranteed present.
    const mapVocab = map.vocab!;
    const mapMerges = map.merges!;
    const mapEncoder = map.encoder as 'byte_level' | 'metaspace';

    this.id = map.id;
    this.map = map;
    this.encoder = mapEncoder;
    this.byteFallbackStart = map.byte_fallback_start ?? -1;

    // Build vocab as a Map for fast lookup.
    const vocab = new Map<string, number>();
    for (const [tok, id] of Object.entries(mapVocab)) vocab.set(tok, id);
    this.vocab = vocab;

    // Build merge ranks. HuggingFace stores merges in priority order — index
    // 0 has highest priority. Each merge is "left right".
    const ranks = new Map<string, number>();
    for (let i = 0; i < mapMerges.length; i++) {
      ranks.set(mapMerges[i]!, i);
    }
    this.mergeRanks = ranks;

    // Pre-tokenizer: prefer the compiled program when present, otherwise
    // fall back to the legacy regex. Programs are required for any client
    // without a Unicode regex engine (libcodec/C); the regex remains
    // useful for compatibility and as a fallback for unrecognised
    // tokenizer families that the maps-cli compiler couldn't lower.
    if (this.encoder === 'byte_level') {
      if (map.pre_tokenizer_program && map.pre_tokenizer_program.ops?.length) {
        this.preTokProgram = map.pre_tokenizer_program as unknown as PreTokProgram;
        this.preTokRegex = null;
      } else if (map.pre_tokenizer_pattern) {
        // Try `'gv'` first (Unicode-sets mode, ES2025), then `'gu'`,
        // then a desugared form. The `(?i:...)` inline-flag group used
        // by every GPT-2-family pre-tokenizer (qwen2, llama-3, phi-4,
        // tiktoken cl100k/o200k, …) is the ES2025 RegExp Pattern
        // Modifiers feature: Chrome <125 (June 2024), iOS Safari <18,
        // Firefox <132, and Node <23 all throw on it. The desugar
        // fallback rewrites `(?i:abc)` → `(?:[aA][bB][cC])` so encoding
        // works on those runtimes. Maps with `pre_tokenizer_program`
        // bypass this path entirely.
        this.preTokRegex = compilePreTokRegexWithFallback(
          map.pre_tokenizer_pattern,
          map.id,
        );
        this.preTokProgram = null;
      } else {
        throw new Error(
          `BPETokenizer: byte_level map "${map.id}" missing both ` +
            `pre_tokenizer_program and pre_tokenizer_pattern.`,
        );
      }
    } else {
      this.preTokRegex = null;
      this.preTokProgram = null;
    }

    // Build the special-token scanner. We accept entries from
    // `map.special_tokens` (the canonical source) AND any vocab key that
    // looks like a delimiter (`<|...|>` or `<...>`). Older maps shipped
    // before a chat-template revision may carry the delimiters in `vocab`
    // but not in `special_tokens` — without the vocab-key fallback, those
    // would still tokenise byte-by-byte. Length-descending order makes
    // the regex match the longest delimiter at any position.
    const specialIds = new Map<string, number>();
    for (const [name, id] of Object.entries(map.special_tokens ?? {})) {
      specialIds.set(name, id);
    }
    for (const [tok, id] of vocab) {
      if (specialIds.has(tok)) continue;
      // Heuristic: `<|body|>` where body is non-empty and identifier-like.
      // Every shipped chat-template tokenizer uses this shape (Qwen,
      // Llama-3, Phi-3/4, DeepSeek, Mistral-Nemo, Gemma). The body
      // constraint excludes pathological vocab BPE tokens like `<|>` in
      // Falcon (id 61799) that happen to share the start/end pair.
      if (isDelimiterShape(tok)) specialIds.set(tok, id);
    }
    this.specialIds = specialIds;
    if (specialIds.size > 0) {
      const escaped = Array.from(specialIds.keys())
        .sort((a, b) => b.length - a.length)
        .map((s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
      this.specialRegex = new RegExp(escaped.join('|'), 'g');
    } else {
      this.specialRegex = null;
    }
  }

  /** Encode text → token IDs. */
  encode(text: string): number[] {
    if (text.length === 0) return [];

    // First pass: split on special tokens. Each special is emitted as its
    // single atomic vocab ID; the gaps between specials are BPE-encoded
    // normally. Mirrors HuggingFace's added-token splitter — without this,
    // `<|im_start|>` would tokenize as 6 byte-level tokens instead of one
    // ID, breaking chat-template round-trips on Qwen/Llama-3/Phi/etc.
    if (this.specialRegex !== null) {
      const out: number[] = [];
      this.specialRegex.lastIndex = 0;
      let cursor = 0;
      let m: RegExpExecArray | null;
      while ((m = this.specialRegex.exec(text)) !== null) {
        if (m.index > cursor) this.encodeChunk(text.slice(cursor, m.index), out);
        out.push(this.specialIds.get(m[0])!);
        cursor = m.index + m[0].length;
        if (m[0].length === 0) this.specialRegex.lastIndex++;
      }
      if (cursor < text.length) this.encodeChunk(text.slice(cursor), out);
      return out;
    }

    const ids: number[] = [];
    this.encodeChunk(text, ids);
    return ids;
  }

  /** BPE-encode a chunk of plain text into `out`. */
  private encodeChunk(text: string, out: number[]): void {
    if (text.length === 0) return;
    const pieces = this.preTokenize(text);
    for (const piece of pieces) {
      const cached = this.cache.get(piece);
      if (cached !== undefined) {
        for (let i = 0; i < cached.length; i++) out.push(cached[i]!);
        continue;
      }
      const encoded = this.encodePieceToVocabSpace(piece);
      const merged = this.applyBPE(encoded);
      const pieceIds = this.lookup(merged);
      this.cache.set(piece, pieceIds);
      for (let i = 0; i < pieceIds.length; i++) out.push(pieceIds[i]!);
    }
  }

  // ── Pre-tokenization ──────────────────────────────────────────────────────

  private preTokenize(text: string): string[] {
    if (this.encoder === 'byte_level') {
      if (this.preTokProgram) {
        return runPreTokProgram(this.preTokProgram, text);
      }
      // Reset regex state and collect non-empty matches.
      const re = this.preTokRegex!;
      re.lastIndex = 0;
      const out: string[] = [];
      let m: RegExpExecArray | null;
      while ((m = re.exec(text)) !== null) {
        if (m[0].length > 0) out.push(m[0]);
        if (m.index === re.lastIndex) re.lastIndex++; // guard against zero-width loops
      }
      return out;
    }

    // Metaspace: split on whitespace, prepend ▁ to each piece. This matches
    // SentencePiece's behavior with `prepend_scheme: "always"`. For
    // `prepend_scheme: "first"` the difference only matters at the very start
    // of input; we approximate the common case correctly.
    const out: string[] = [];
    const trimmed = text.replace(/[ \t]+/g, ' ');
    // Treat a leading space as part of the first word.
    const parts = trimmed.split(/(\s)/).filter((p) => p.length > 0);
    for (const p of parts) {
      if (p === ' ') continue;
      out.push(METASPACE + p);
    }
    return out;
  }

  // ── Step 2: encode piece → vocab character space ─────────────────────────

  private encodePieceToVocabSpace(piece: string): string[] {
    if (this.encoder === 'byte_level') {
      const bytes = new TextEncoder().encode(piece);
      const encoded = encodeByteLevelChars(bytes);
      // Each codepoint of `encoded` is one initial BPE token.
      return [...encoded];
    }
    // Metaspace: the piece is already in vocab-space (▁ prefix). Each
    // codepoint of the piece is one initial BPE token.
    return [...piece];
  }

  // ── Step 3: BPE merges ────────────────────────────────────────────────────

  private applyBPE(tokens: string[]): string[] {
    if (tokens.length < 2) return tokens;

    let parts = tokens.slice();
    while (true) {
      // Find the lowest-rank (highest-priority) mergeable pair.
      let bestIdx = -1;
      let bestRank = Infinity;
      for (let i = 0; i < parts.length - 1; i++) {
        const key = parts[i] + ' ' + parts[i + 1];
        const r = this.mergeRanks.get(key);
        if (r !== undefined && r < bestRank) {
          bestRank = r;
          bestIdx = i;
        }
      }
      if (bestIdx === -1) break;

      // Merge ALL non-overlapping occurrences of that pair in one pass —
      // this matches HuggingFace's behavior and runs in linear time per
      // outer iteration.
      const left = parts[bestIdx]!;
      const right = parts[bestIdx + 1]!;
      const merged = left + right;
      const next: string[] = [];
      let i = 0;
      while (i < parts.length) {
        if (i < parts.length - 1 && parts[i] === left && parts[i + 1] === right) {
          next.push(merged);
          i += 2;
        } else {
          next.push(parts[i]!);
          i += 1;
        }
      }
      parts = next;
    }

    return parts;
  }

  // ── Step 4: vocab lookup with byte fallback ──────────────────────────────

  private lookup(tokens: string[]): number[] {
    const ids: number[] = [];
    for (const tok of tokens) {
      const id = this.vocab.get(tok);
      if (id !== undefined) {
        ids.push(id);
        continue;
      }
      // Byte fallback (metaspace + SentencePiece byte_fallback): emit the
      // raw UTF-8 bytes of the token as byte-fallback IDs.
      if (this.byteFallbackStart >= 0) {
        const bytes = new TextEncoder().encode(tok);
        for (let i = 0; i < bytes.length; i++) {
          ids.push(this.byteFallbackStart + bytes[i]!);
        }
      }
      // For byte_level this branch is unreachable in well-formed input — every
      // byte has a vocab entry — so we silently drop. (Defensive: should never
      // happen for valid maps and well-formed UTF-8 input.)
    }
    return ids;
  }
}

/** Convenience one-shot encoder. */
export function bpeEncode(map: TokenizerMap, text: string): number[] {
  return new BPETokenizer(map).encode(text);
}

// ── pre-tokenizer regex compilation with runtime-fallback ──────────────────

/**
 * Compile a `pre_tokenizer_pattern` to a RegExp across the runtime matrix
 * we ship to. Three escalating attempts:
 *
 *   1. `'gv'` (Unicode-sets, ES2024) — preferred for newer maps.
 *   2. `'gu'` (Unicode, ES2018) — covers maps that don't need set notation.
 *   3. Desugar `(?i:...)` inline-flag groups, then retry `'gu'`.
 *
 * The third step is what unblocks older runtimes: Chrome <125, iOS Safari
 * <18, Firefox <132, and Node <23 all throw on the ES2025 RegExp Pattern
 * Modifiers syntax that every GPT-2-family pre-tokenizer uses for its
 * contractions group. Desugaring rewrites it to a portable form.
 *
 * Maps that carry `pre_tokenizer_program` skip this path entirely.
 */
export function compilePreTokRegexWithFallback(
  pattern: string,
  mapId: string,
): RegExp {
  // 1. gv (Unicode-sets)
  try {
    return new RegExp(pattern, 'gv');
  } catch { /* fall through */ }

  // 2. gu (Unicode)
  try {
    return new RegExp(pattern, 'gu');
  } catch { /* fall through */ }

  // 3. Desugar `(?i:...)` and retry with `gu`. If the runtime still
  //    rejects, throw with a clear error pointing at the durable fix.
  const desugared = desugarInlineFlagGroups(pattern);
  try {
    return new RegExp(desugared, 'gu');
  } catch (err) {
    throw new Error(
      `BPETokenizer: cannot compile pre_tokenizer_pattern for "${mapId}" ` +
        `on this runtime even after desugaring inline-flag groups. ` +
        `Original error: ${(err as Error).message}. ` +
        `Durable fix: regenerate the map with \`codecai-maps build\` so it ` +
        `carries a \`pre_tokenizer_program\` and skips the regex path.`,
    );
  }
}

/**
 * Match `<|body|>` where `body` is non-empty and identifier-like
 * (letters/digits/`_`/`-`). Catches every shipped chat-template and
 * tool-call delimiter while excluding pathological vocab BPE tokens
 * like Falcon's `<|>` (id 61799) that share the start/end pair.
 */
function isDelimiterShape(tok: string): boolean {
  if (tok.length <= 4) return false;
  if (!tok.startsWith('<|') || !tok.endsWith('|>')) return false;
  const body = tok.slice(2, -2);
  return /^[A-Za-z0-9_-]+$/.test(body);
}

/**
 * Rewrite `(?i:body)` → `(?:body')` where `body'` replaces every cased
 * letter `x` with `[xX]`. Used to make GPT-2-family contractions groups
 * compile on runtimes without ES2025 RegExp Pattern Modifiers.
 *
 * Limitations (acceptable for tokenizer pre-tokenizers, which never
 * exercise these shapes):
 *   - assumes the body has no nested groups or unescaped `)`.
 *   - leaves character classes `[...]` and escapes `\x` alone — only
 *     bare letters are expanded.
 */
export function desugarInlineFlagGroups(pattern: string): string {
  return pattern.replace(/\(\?i:([^)]*)\)/g, (_, body: string) => {
    let out = '';
    let i = 0;
    while (i < body.length) {
      const ch = body[i]!;
      if (ch === '\\' && i + 1 < body.length) {
        // Pass `\x` escapes through unchanged.
        out += ch + body[i + 1];
        i += 2;
        continue;
      }
      if (ch === '[') {
        // Pass character classes through; expanding cased letters inside
        // them would change semantics (a `[a-z]` range is not `[aA-zZ]`).
        const end = body.indexOf(']', i);
        if (end === -1) { out += body.slice(i); break; }
        out += body.slice(i, end + 1);
        i = end + 1;
        continue;
      }
      const upper = ch.toUpperCase();
      const lower = ch.toLowerCase();
      if (upper !== lower) {
        out += '[' + lower + upper + ']';
      } else {
        out += ch;
      }
      i++;
    }
    return '(?:' + out + ')';
  });
}

/**
 * Shared encoder utilities — the GPT-2 byte↔unicode mapping table and
 * UTF-8 partial-sequence buffering. Used by both the Detokenizer (to recover
 * bytes from byte-level tokens) and the BPETokenizer (to encode input bytes
 * into the vocab's character space).
 */

/**
 * Build the GPT-2 byte→unicode mapping table.
 *
 * The 256-entry bijection used by tiktoken / GPT-2 / Llama-3 / Qwen2 BPE
 * tokenizers. Bytes 33-126 (printable ASCII), 161-172, 174-255 map to
 * themselves as Unicode characters; all other bytes map to characters
 * starting at U+0100 (`Ā`).
 */
function buildByteToUnicode(): { byteToChar: Map<number, string>; charToByte: Map<number, number> } {
  const bs: number[] = [];
  for (let i = 33; i <= 126; i++) bs.push(i);
  for (let i = 161; i <= 172; i++) bs.push(i);
  for (let i = 174; i <= 255; i++) bs.push(i);
  const cs = bs.slice();
  let n = 0;
  for (let b = 0; b < 256; b++) {
    if (!bs.includes(b)) {
      bs.push(b);
      cs.push(256 + n);
      n++;
    }
  }
  const byteToChar = new Map<number, string>();
  const charToByte = new Map<number, number>();
  for (let i = 0; i < bs.length; i++) {
    const ch = String.fromCodePoint(cs[i]!);
    byteToChar.set(bs[i]!, ch);
    charToByte.set(cs[i]!, bs[i]!);
  }
  return { byteToChar, charToByte };
}

const TABLES = buildByteToUnicode();
export const BYTE_TO_CHAR: ReadonlyMap<number, string> = TABLES.byteToChar;
export const CHAR_TO_BYTE: ReadonlyMap<number, number> = TABLES.charToByte;

/**
 * Decode a byte-level BPE token string (e.g. `"Ġhello"`) to its raw bytes
 * by reversing the GPT-2 byte→unicode table. Characters outside the table
 * are emitted as their UTF-8 bytes (defensive — shouldn't happen for valid
 * vocab tokens but keeps the decoder total).
 */
export function decodeByteLevelToken(rawToken: string): Uint8Array {
  const out: number[] = [];
  for (const ch of rawToken) {
    const cp = ch.codePointAt(0)!;
    const b = CHAR_TO_BYTE.get(cp);
    if (b !== undefined) {
      out.push(b);
    } else {
      const utf8 = new TextEncoder().encode(ch);
      for (let i = 0; i < utf8.length; i++) out.push(utf8[i]!);
    }
  }
  return new Uint8Array(out);
}

/**
 * Encode raw bytes into a string of GPT-2 byte-encoded characters. Used by
 * the BPE tokenizer — input text is split into pieces, each piece is encoded
 * to UTF-8 bytes, then each byte is mapped through this table to produce a
 * string that matches the keys of the model's vocab.
 */
export function encodeByteLevelChars(bytes: Uint8Array): string {
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    out += BYTE_TO_CHAR.get(bytes[i]!)!;
  }
  return out;
}

/**
 * The metaspace marker — a single character used by SentencePiece-derived
 * tokenizers to denote a space prefix. Llama-2, Mistral-v3, Mixtral, Gemma
 * all use this convention.
 */
export const METASPACE = '▁'; // ▁

/**
 * Frame stream decoders. Adapt a transport-level `ReadableStream<Uint8Array>`
 * (typically `fetch().body`) into a typed `AsyncIterable<CodecFrame>`.
 *
 * Two formats are supported, both emitted by the vLLM Codec server:
 *
 *   msgpack  — concatenated MessagePack maps. Decoded with the official
 *              streaming unpacker (`decodeMultiStream`), which handles frame
 *              boundaries that fall inside a single msgpack object.
 *
 *   protobuf — 4-byte big-endian length prefix followed by raw CodecFrame
 *              bytes. We do the framing manually here to avoid pulling in a
 *              full protobuf runtime for one tiny message.
 */
import { decodeMultiStream } from '@msgpack/msgpack';

import type { CodecFrame } from './types.js';

/** Unified entry point — picks the decoder based on the format hint. */
export function decodeStream(
  stream: ReadableStream<Uint8Array>,
  format: 'msgpack' | 'protobuf' = 'msgpack'
): AsyncIterable<CodecFrame> {
  return format === 'msgpack' ? decodeMsgpackStream(stream) : decodeProtobufStream(stream);
}

// ── MessagePack ───────────────────────────────────────────────────────────────

export async function* decodeMsgpackStream(
  stream: ReadableStream<Uint8Array>
): AsyncIterable<CodecFrame> {
  for await (const value of decodeMultiStream(stream)) {
    const frame = value as { ids: number[]; done: boolean; finish_reason?: string };
    yield { ids: frame.ids, done: frame.done, finish_reason: frame.finish_reason };
    if (frame.done) return;
  }
}

// ── Protobuf ──────────────────────────────────────────────────────────────────

export async function* decodeProtobufStream(
  stream: ReadableStream<Uint8Array>
): AsyncIterable<CodecFrame> {
  const reader = stream.getReader();
  let buffer = new Uint8Array(0);

  try {
    while (true) {
      // Need at least 4 bytes for the length prefix.
      while (buffer.length < 4) {
        const { done, value } = await reader.read();
        if (done) {
          if (buffer.length > 0) {
            throw new Error(`Codec protobuf stream ended mid-frame (${buffer.length} bytes left)`);
          }
          return;
        }
        buffer = concat(buffer, value);
      }

      const frameLen = new DataView(
        buffer.buffer,
        buffer.byteOffset,
        buffer.byteLength
      ).getUint32(0, false);

      while (buffer.length < 4 + frameLen) {
        const { done, value } = await reader.read();
        if (done) {
          throw new Error(`Codec protobuf stream ended mid-frame (need ${frameLen} bytes)`);
        }
        buffer = concat(buffer, value);
      }

      const payload = buffer.subarray(4, 4 + frameLen);
      buffer = buffer.subarray(4 + frameLen);

      const frame = decodeProtobufFrame(payload);
      yield frame;
      if (frame.done) return;
    }
  } finally {
    reader.releaseLock();
  }
}

function concat(a: Uint8Array, b: Uint8Array | Uint8Array<ArrayBuffer>): Uint8Array<ArrayBuffer> {
  const len = a.length + b.length;
  const out = new Uint8Array(len);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

function decodeVarint(data: Uint8Array, pos: number): [number, number] {
  let result = 0;
  let shift = 0;
  while (true) {
    if (pos >= data.length) throw new Error('Codec protobuf: truncated varint');
    const b = data[pos++]!;
    result |= (b & 0x7f) << shift;
    if ((b & 0x80) === 0) return [result, pos];
    shift += 7;
    if (shift > 35) throw new Error('Codec protobuf: varint too long');
  }
}

const TEXT_DEC = new TextDecoder();

/** Decode a single CodecFrame protobuf payload (no length prefix). */
export function decodeProtobufFrame(data: Uint8Array): CodecFrame {
  const ids: number[] = [];
  let done = false;
  let finishReason: string | undefined;
  let pos = 0;

  while (pos < data.length) {
    let tag: number;
    [tag, pos] = decodeVarint(data, pos);
    const field = tag >> 3;
    const wt = tag & 0x7;

    if (wt === 0) {
      let val: number;
      [val, pos] = decodeVarint(data, pos);
      if (field === 2) done = val !== 0;
    } else if (wt === 1) {
      // 64-bit — not used in CodecFrame, skip.
      pos += 8;
    } else if (wt === 2) {
      let len: number;
      [len, pos] = decodeVarint(data, pos);
      const payload = data.subarray(pos, pos + len);
      pos += len;
      if (field === 1) {
        let p = 0;
        while (p < payload.length) {
          let v: number;
          [v, p] = decodeVarint(payload, p);
          ids.push(v);
        }
      } else if (field === 3) {
        finishReason = TEXT_DEC.decode(payload);
      }
    } else if (wt === 5) {
      // 32-bit — not used, skip.
      pos += 4;
    } else {
      throw new Error(`Codec protobuf: unsupported wire type ${wt}`);
    }
  }

  return { ids, done, finish_reason: finishReason };
}

/**
 * Pre-tokenizer program interpreter.
 *
 * Executes a `pre_tokenizer_program` against an input string, producing
 * the same sequence of pieces that the legacy `pre_tokenizer_pattern`
 * regex would have produced. See spec/PRETOKENIZER_PROGRAM.md for the
 * design rationale and op set.
 *
 * The runtime uses native regex for Unicode class queries (\p{L}, \p{N})
 * — no shipped Unicode tables. C and other regex-less runtimes will
 * supply their own class-membership facility.
 *
 * METASPACE op for SentencePiece is delegated to a tiny inline splitter;
 * the rest of this module only handles GPT-2-family op execution.
 */
import { METASPACE } from './encoder.js';

// ── Op types ────────────────────────────────────────────────────────────────

export interface OpLiteralsCi {
  readonly op: 'literals_ci';
  readonly patterns: readonly string[];
}
/** Case-sensitive literal alternatives — like `literals_ci` but matches
 * case-exact. Used by older OpenAI tokenizers (p50k_base, r50k_base) whose
 * contractions group `'s|'t|'re|'ve|'m|'ll|'d` is not wrapped in `(?i:)`. */
export interface OpLiterals {
  readonly op: 'literals';
  readonly patterns: readonly string[];
}
export interface OpLetters {
  readonly op: 'letters';
  /** Match `[^\r\n\p{L}\p{N}]?\p{L}+` — at most one lead char that's none of
   * those. Mutually exclusive with `lead_space`. */
  readonly lead_other?: boolean;
  /** Match ` ?\p{L}+` — at most one literal-space lead. Used by older OpenAI
   * tokenizers. Mutually exclusive with `lead_other`. */
  readonly lead_space?: boolean;
}
export interface OpNumbers {
  readonly op: 'numbers';
  /** Max digit run length. Omit / 0 for unbounded. */
  readonly max_run?: number;
  /** Match ` ?\p{N}+` (or ` ?\p{N}{1,K}`) — at most one literal-space lead.
   * Used by older OpenAI tokenizers. */
  readonly lead_space?: boolean;
}
export interface OpPunctRun {
  readonly op: 'punct_run';
  readonly lead_space?: boolean;
  readonly trailing_newlines?: boolean;
  /** Override `trailing_newlines` with an explicit charset. Each character
   * in the string is accepted in the trailing run. Used by o200k_base /
   * mistral-nemo which trail on `[\r\n/]` (note the `/`) rather than
   * just `[\r\n]`. */
  readonly trailing_chars?: string;
}
/** Cased-letter run with optional trailing case-insensitive contractions.
 * Used by o200k_base / mistral-nemo, which split words on case boundaries
 * (e.g. "MyCamelCase" → ["My", "Camel", "Case"]).
 *
 *   kind: "title"  →  [Lu Lt Lm Lo M]* [Ll Lm Lo M]+   (zero-or-more upper, then 1+ lower)
 *   kind: "upper"  →  [Lu Lt Lm Lo M]+ [Ll Lm Lo M]*   (one-or-more upper, then 0+ lower)
 *
 * `lead_other: true` prepends `[^\r\n\p{L}\p{N}]?` (the conventional GPT-2
 * lead-other guard). `trailing_ci`, when set, is the same as the legacy
 * `literals_ci` ASCII case-fold semantics. */
export interface OpLettersCased {
  readonly op: 'letters_cased';
  readonly kind: 'title' | 'upper';
  readonly lead_other?: boolean;
  readonly trailing_ci?: readonly string[];
}
export interface OpNewlineBlock { readonly op: 'newline_block' }
export interface OpTrailingWs   { readonly op: 'trailing_ws' }
export interface OpWsRun        { readonly op: 'ws_run' }
export interface OpMetaspace {
  readonly op: 'metaspace_split';
  readonly prefix_first?: boolean;
}

export type PreTokOp =
  | OpLiteralsCi | OpLiterals | OpLetters | OpLettersCased | OpNumbers
  | OpPunctRun | OpNewlineBlock | OpTrailingWs | OpWsRun | OpMetaspace;

export interface PreTokProgram {
  readonly version: number;
  readonly ops: readonly PreTokOp[];
}

// ── Class predicates (native regex; no Unicode data shipped) ─────────────────

const RE_LETTER = /\p{L}/u;
const RE_NUMBER = /\p{N}/u;
/* The pre-tok regex's `\s` is broader than ASCII space — matches Unicode
 * White_Space. We use the same `\s` semantics native regex provides. */
const RE_WS = /\s/u;
/** "Upper cluster" of the o200k_base / mistral-nemo `letters_cased` op.
 * `\p{Lu}` (uppercase) + `\p{Lt}` (titlecase) + the shared `\p{Lm}` /
 * `\p{Lo}` / `\p{M}` set that's also valid in the lower cluster. */
const RE_LETTER_UPPER = /[\p{Lu}\p{Lt}\p{Lm}\p{Lo}\p{M}]/u;
/** "Lower cluster" — `\p{Ll}` + the shared modifier / other-letter / mark
 * categories. */
const RE_LETTER_LOWER = /[\p{Ll}\p{Lm}\p{Lo}\p{M}]/u;
const isLetter = (cp: string): boolean => RE_LETTER.test(cp);
const isNumber = (cp: string): boolean => RE_NUMBER.test(cp);
const isWs     = (cp: string): boolean => RE_WS.test(cp);
const isLetterUpper = (cp: string): boolean => RE_LETTER_UPPER.test(cp);
const isLetterLower = (cp: string): boolean => RE_LETTER_LOWER.test(cp);

/** Returns the next code point at index `i` and the index after it. */
function nextCp(s: string, i: number): { cp: string; next: number } {
  const code = s.codePointAt(i)!;
  const cp   = String.fromCodePoint(code);
  return { cp, next: i + cp.length };
}

// ── Per-op matchers ─────────────────────────────────────────────────────────
//
// Each matcher returns the number of UTF-16 code units consumed at
// position `i`, or 0 if it doesn't match. The interpreter loop then
// emits that span and advances.

function matchLiteralsCi(op: OpLiteralsCi, s: string, i: number): number {
  let best = 0;
  for (const p of op.patterns) {
    if (p.length <= best) continue;
    if (i + p.length > s.length) continue;
    let ok = true;
    for (let k = 0; k < p.length; k++) {
      const a = s.charCodeAt(i + k);
      const b = p.charCodeAt(k);
      if (a === b) continue;
      // ASCII case fold
      if (a >= 65 && a <= 90  && a + 32 === b) continue;
      if (a >= 97 && a <= 122 && a - 32 === b) continue;
      ok = false; break;
    }
    if (ok) best = p.length;
  }
  return best;
}

function matchLiterals(op: OpLiterals, s: string, i: number): number {
  let best = 0;
  for (const p of op.patterns) {
    if (p.length <= best) continue;
    if (i + p.length > s.length) continue;
    let ok = true;
    for (let k = 0; k < p.length; k++) {
      if (s.charCodeAt(i + k) !== p.charCodeAt(k)) { ok = false; break; }
    }
    if (ok) best = p.length;
  }
  return best;
}

function matchLetters(op: OpLetters, s: string, i: number): number {
  let p = i;
  if (op.lead_other) {
    /* `[^\r\n\p{L}\p{N}]?` — at most one char that's none of those. */
    const { cp, next } = nextCp(s, p);
    if (next > p && cp !== '\r' && cp !== '\n' && !isLetter(cp) && !isNumber(cp)) {
      p = next;
    }
  } else if (op.lead_space) {
    /* ` ?` — at most one literal space. */
    if (s.charCodeAt(p) === 0x20) p += 1;
  }
  /* `\p{L}+` */
  const runStart = p;
  while (p < s.length) {
    const { cp, next } = nextCp(s, p);
    if (!isLetter(cp)) break;
    p = next;
  }
  if (p === runStart) {
    /* No letter run — back out the lead char. */
    return 0;
  }
  return p - i;
}

function matchNumbers(op: OpNumbers, s: string, i: number): number {
  let p = i;
  if (op.lead_space && s.charCodeAt(p) === 0x20) p += 1;
  const runStart = p;
  let count = 0;
  const max = op.max_run && op.max_run > 0 ? op.max_run : Infinity;
  while (p < s.length && count < max) {
    const { cp, next } = nextCp(s, p);
    if (!isNumber(cp)) break;
    p = next;
    count++;
  }
  if (p === runStart) return 0;
  return p - i;
}

function matchPunctRun(op: OpPunctRun, s: string, i: number): number {
  let p = i;
  if (op.lead_space) {
    if (s.charCodeAt(p) === 0x20) p += 1;
  }
  /* `[^\s\p{L}\p{N}]+` */
  let runStart = p;
  while (p < s.length) {
    const { cp, next } = nextCp(s, p);
    if (isWs(cp) || isLetter(cp) || isNumber(cp)) break;
    p = next;
  }
  if (p === runStart) {
    /* No punct run; the lead space alone doesn't constitute a match. */
    return 0;
  }
  // Trailing chars: prefer explicit `trailing_chars` charset (used by
  // o200k_base / mistral-nemo, which trail on `[\r\n/]`). Fall back to
  // the legacy `trailing_newlines: true` boolean → `\r\n`.
  if (op.trailing_chars !== undefined) {
    while (p < s.length && op.trailing_chars.indexOf(s.charAt(p)) >= 0) {
      p++;
    }
  } else if (op.trailing_newlines) {
    while (p < s.length) {
      const c = s.charCodeAt(p);
      if (c === 0x0A || c === 0x0D) p++;
      else break;
    }
  }
  return p - i;
}

function matchLettersCased(op: OpLettersCased, s: string, i: number): number {
  let p = i;
  if (op.lead_other) {
    const { cp, next } = nextCp(s, p);
    if (next > p && cp !== '\r' && cp !== '\n' && !isLetter(cp) && !isNumber(cp)) {
      p = next;
    }
  }

  // Greedily consume prefix-set chars and record each step as a candidate
  // suffix-start checkpoint. Lm/Lo/M are in BOTH sets so the longest
  // match may need to backtrack one or more chars from the greedy run
  // to let the suffix consume them. We try suffix from each checkpoint
  // longest-first; first match wins.
  const checkpoints: number[] = [p];
  while (p < s.length) {
    const { cp, next } = nextCp(s, p);
    if (!isLetterUpper(cp)) break;
    p = next;
    checkpoints.push(p);
  }

  const minPrefix = op.kind === 'upper' ? 1 : 0;
  const minSuffix = op.kind === 'title' ? 1 : 0;

  for (let k = checkpoints.length - 1; k >= 0; k--) {
    if (k < minPrefix) break; // not enough prefix chars, regardless of suffix
    let q = checkpoints[k]!;
    let suffixCount = 0;
    while (q < s.length) {
      const { cp, next } = nextCp(s, q);
      if (!isLetterLower(cp)) break;
      q = next;
      suffixCount++;
    }
    if (suffixCount < minSuffix) continue;

    // Optional case-insensitive trailing contractions, longest match wins.
    if (op.trailing_ci && op.trailing_ci.length > 0) {
      let best = 0;
      for (const pat of op.trailing_ci) {
        if (pat.length <= best || q + pat.length > s.length) continue;
        let ok = true;
        for (let m = 0; m < pat.length; m++) {
          const a = s.charCodeAt(q + m);
          const b = pat.charCodeAt(m);
          if (a === b) continue;
          if (a >= 65 && a <= 90  && a + 32 === b) continue;
          if (a >= 97 && a <= 122 && a - 32 === b) continue;
          ok = false; break;
        }
        if (ok) best = pat.length;
      }
      q += best;
    }

    return q - i;
  }
  return 0;
}

function matchNewlineBlock(_op: OpNewlineBlock, s: string, i: number): number {
  /* `\s*[\r\n]+` — must contain at least one newline. */
  let p = i;
  let lastNonNl = p;
  /* Greedy \s* */
  while (p < s.length) {
    const { cp, next } = nextCp(s, p);
    if (!isWs(cp)) break;
    if (cp !== '\r' && cp !== '\n') lastNonNl = next;
    p = next;
  }
  /* Now back up to the start of the trailing [\r\n]+ run. */
  /* The regex form `\s*[\r\n]+` gobbles \s* greedily, then requires a
   * newline at the position after it. Standard regex implementations
   * backtrack the \s* to find a newline-anchor. We replicate by
   * scanning forward: find the last index ≤ p that contains a newline,
   * and require at least one. */
  /* Scan from the original i: find first newline, consume everything
   * up through the contiguous newline run. */
  let firstNl = -1;
  for (let q = i; q < p; q++) {
    const c = s.charCodeAt(q);
    if (c === 0x0A || c === 0x0D) { firstNl = q; break; }
  }
  if (firstNl < 0) return 0;
  /* We need to consume [\s* up through final newline run]. The match
   * spans from i through the last contiguous run of newlines that
   * starts somewhere within [firstNl, p). Since regex `\s*[\r\n]+` is
   * the same as "all whitespace ending in a newline", we trim back any
   * trailing non-newline whitespace from p. */
  let q = p;
  while (q > firstNl) {
    const c = s.charCodeAt(q - 1);
    if (c === 0x0A || c === 0x0D) break;
    q--;
  }
  return q - i;
  void lastNonNl;
}

function matchTrailingWs(_op: OpTrailingWs, s: string, i: number): number {
  /* `\s+(?!\S)` with backtracking semantics.
   *
   * The regex doesn't actually require the run to reach end-of-input —
   * it requires the character AFTER the matched span to not be \S
   * (non-whitespace). Since whitespace itself satisfies `not \S`, the
   * regex engine backs off `\s+` until either the run ends at EOI
   * (whole run matches) or the position after the match is whitespace
   * (one code point shorter than the maximal run). The longest viable
   * match is therefore:
   *   - whole run, if run ends at EOI
   *   - run length minus the final whitespace code point, if it ends
   *     at non-whitespace
   * Returns 0 when there's no match (single-cp run followed by \S, or
   * not whitespace at all).
   */
  let p = i;
  while (p < s.length) {
    const { cp, next } = nextCp(s, p);
    if (!isWs(cp)) break;
    p = next;
  }
  if (p === i) return 0;           // not whitespace at all
  if (p === s.length) return p - i; // run reaches EOI → match whole run

  // Followed by non-whitespace. Truncate before the LAST whitespace
  // code point in the run.
  let q = i;
  let lastStart = i;
  while (q < p) {
    lastStart = q;
    q = nextCp(s, q).next;
  }
  return lastStart - i;            // 0 if run was a single code point
}

function matchWsRun(_op: OpWsRun, s: string, i: number): number {
  let p = i;
  while (p < s.length) {
    const { cp, next } = nextCp(s, p);
    if (!isWs(cp)) break;
    p = next;
  }
  return p - i;
}

// ── Interpreter loop ────────────────────────────────────────────────────────

/**
 * Run a pre-tokenizer program over an input string.
 *
 * For metaspace-style programs (SentencePiece), recognize the single-op
 * shortcut and delegate to a dedicated splitter — the GPT-2-family loop
 * below isn't applicable.
 */
export function runPreTokProgram(
  prog: PreTokProgram, text: string,
): string[] {
  // Single-op metaspace shortcut.
  if (prog.ops.length === 1 && prog.ops[0]!.op === 'metaspace_split') {
    return runMetaspace(prog.ops[0] as OpMetaspace, text);
  }

  const out: string[] = [];
  const n = text.length;
  let i = 0;
  outer: while (i < n) {
    for (const op of prog.ops) {
      let span = 0;
      switch (op.op) {
        case 'literals_ci':   span = matchLiteralsCi(op, text, i);  break;
        case 'literals':      span = matchLiterals(op, text, i);    break;
        case 'letters':       span = matchLetters(op, text, i);     break;
        case 'letters_cased': span = matchLettersCased(op, text, i); break;
        case 'numbers':       span = matchNumbers(op, text, i);     break;
        case 'punct_run':     span = matchPunctRun(op, text, i);    break;
        case 'newline_block': span = matchNewlineBlock(op, text, i); break;
        case 'trailing_ws':   span = matchTrailingWs(op, text, i);  break;
        case 'ws_run':        span = matchWsRun(op, text, i);       break;
        case 'metaspace_split':
          /* Mixed programs aren't legal — metaspace is single-op. Skip. */
          continue;
      }
      if (span > 0) {
        out.push(text.slice(i, i + span));
        i += span;
        continue outer;
      }
    }
    /* Defensive fallback: no op matched. Emit one Unicode scalar value
     * and advance. Well-formed programs end with `ws_run` (and any
     * non-ws becomes a `letters`/`numbers`/`punct_run` match), so this
     * branch is unreachable for valid GPT-2-family programs but
     * provides graceful degradation if a pathological input slips in. */
    const { cp, next } = nextCp(text, i);
    out.push(cp);
    i = next;
  }
  return out;
}

function runMetaspace(op: OpMetaspace, text: string): string[] {
  const out: string[] = [];
  const trimmed = text.replace(/[ \t]+/g, ' ');
  const parts = trimmed.split(/(\s)/).filter((p) => p.length > 0);
  let isFirst = true;
  for (const p of parts) {
    if (p === ' ') { isFirst = false; continue; }
    if (op.prefix_first && isFirst) {
      out.push(p);
    } else {
      out.push(METASPACE + p);
    }
    isFirst = false;
  }
  return out;
}

/**
 * Codec latent-modality frame encoding (v0.3+).
 *
 * TypeScript twin of `packages/python/src/codecai/server/latent_frame.py`.
 * Same wire shape, same pipeline math, same conformance fixtures
 * (`packages/bench/golden/pipelines/<name>/`). The Python file is the
 * canonical reference encoder; this module is its byte-for-byte twin
 * for browser + Node + edge runtimes.
 *
 * Wire format (msgpack):
 *   Header — first frame in the response body:
 *     { type: 'header',
 *       latent_space_id: string, shape: number[], dtype: string,
 *       pipeline: string,
 *       scales?: Uint8Array, fps?: number,
 *       total_frames?: number, vae_scale_factor?: number }
 *   Frame  — every subsequent frame:
 *     { data: Uint8Array, seq: number, keyframe: boolean,
 *       done: boolean, finish_reason?: string }
 *
 * Pipeline math is pinned in spec/PIPELINES.md. This module implements
 * forward (server-side) AND inverse (client-side) for all seven
 * pipelines. The protobuf encoder is intentionally NOT ported in this
 * pass — msgpack is the primary v0.3 wire format and the protobuf side
 * is a straight follow-up against the same Python reference.
 */

import { encode as msgpackEncode, decode as msgpackDecode } from '@msgpack/msgpack';

// ── Pipeline registry (mirrors PIPELINE_NAMES in latent_frame.py) ───────────

export const PIPELINE_NAMES = [
  'raw',
  'int8',
  'int4',
  'int8-adaptive',
  'int4-adaptive',
  'delta+int8',
  'delta+int4',
] as const;

export type PipelineName = (typeof PIPELINE_NAMES)[number];

const STATIC_SCALE_PIPELINES = new Set<PipelineName>(['int8', 'int4']);
const ADAPTIVE_SCALE_PIPELINES = new Set<PipelineName>([
  'int8-adaptive', 'int4-adaptive', 'delta+int8', 'delta+int4',
]);
const DELTA_PIPELINES = new Set<PipelineName>(['delta+int8', 'delta+int4']);
const INT4_PIPELINES = new Set<PipelineName>([
  'int4', 'int4-adaptive', 'delta+int4',
]);

export type LatentDtype = 'fp32' | 'fp16' | 'bf16' | 'int8' | 'int4';

// ── Public types ────────────────────────────────────────────────────────────

/** Every latent stream begins with exactly one header. */
export interface LatentStreamHeader {
  readonly latent_space_id: string;
  readonly shape: readonly number[];
  readonly dtype: LatentDtype;
  readonly pipeline: PipelineName;
  /** Static-scale pipelines only: fp16 LE bytes of length 2*C. */
  readonly scales?: Uint8Array;
  readonly fps?: number;
  readonly total_frames?: number;
  readonly vae_scale_factor?: number;
}

/** Every frame after the header. */
export interface LatentFrame {
  readonly data: Uint8Array;
  readonly seq: number;
  readonly keyframe: boolean;
  readonly done: boolean;
  readonly finish_reason?: string;
}

// ── fp16 helpers (no native JS support — pack via DataView) ─────────────────

/**
 * Pack one fp32 number into a uint16 IEEE 754 fp16 representation. Round-half-
 * to-even, full subnormal/Inf/NaN handling. Matches numpy's float16
 * conversion bit-for-bit on common inputs (modulo platform-specific NaN
 * payload bits, which msgpack ships opaquely as bytes anyway).
 */
function f32ToF16(value: number): number {
  const f32 = new Float32Array(1);
  const u32 = new Uint32Array(f32.buffer);
  f32[0] = value;
  const x = u32[0]!;
  const sign = (x >>> 16) & 0x8000;
  const expo = ((x >>> 23) & 0xff) - (127 - 15);
  const mant = x & 0x7fffff;

  if (expo >= 0x1f) {
    // Inf or NaN → fp16 Inf or quiet NaN. Preserve mantissa truthiness.
    return sign | 0x7c00 | (mant ? 0x0200 : 0);
  }
  if (expo <= 0) {
    // Subnormal or zero. Shift mantissa right by (1 - expo); add hidden 1
    // back when expo > -10 (otherwise it underflows to 0).
    if (expo < -10) return sign;
    const m = (mant | 0x800000) >>> (1 - expo);
    // Round-half-to-even: add 0x1000 if next bit is 1 AND (sticky OR even).
    const round = m & 0x1fff;
    let result = m >>> 13;
    if (round > 0x1000 || (round === 0x1000 && (result & 1))) result++;
    return sign | result;
  }
  // Normal range. Pack expo + mantissa, then round-half-to-even.
  const round = mant & 0x1fff;
  let h = sign | (expo << 10) | (mant >>> 13);
  if (round > 0x1000 || (round === 0x1000 && (h & 1))) h++;
  return h;
}

function f16ToF32(u16: number): number {
  const sign = (u16 & 0x8000) >>> 15;
  const expo = (u16 & 0x7c00) >>> 10;
  const mant = u16 & 0x03ff;
  if (expo === 0) {
    if (mant === 0) return sign ? -0 : 0;
    // Subnormal: 2^-14 * (mant / 1024)
    return (sign ? -1 : 1) * Math.pow(2, -14) * (mant / 1024);
  }
  if (expo === 0x1f) {
    if (mant === 0) return sign ? -Infinity : Infinity;
    return NaN;
  }
  // Normal: (-1)^s * 2^(expo-15) * (1 + mant/1024)
  return (sign ? -1 : 1) * Math.pow(2, expo - 15) * (1 + mant / 1024);
}

/** Encode a Float32Array of per-channel scales as C × 2 LE fp16 bytes. */
export function scalesToBytes(scales: Float32Array): Uint8Array {
  const out = new Uint8Array(scales.length * 2);
  const view = new DataView(out.buffer);
  for (let i = 0; i < scales.length; i++) {
    view.setUint16(i * 2, f32ToF16(scales[i]!), true /* little-endian */);
  }
  return out;
}

/** Decode C × 2 LE fp16 bytes into a Float32Array of length C. */
export function scalesFromBytes(bytes: Uint8Array): Float32Array {
  if (bytes.length % 2 !== 0) {
    throw new Error(`scales byte length must be even (got ${bytes.length})`);
  }
  const C = bytes.length / 2;
  const out = new Float32Array(C);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  for (let i = 0; i < C; i++) {
    out[i] = f16ToF32(view.getUint16(i * 2, true));
  }
  return out;
}

// ── Pipeline math (mirrors latent_frame.py forward path) ────────────────────

/**
 * Per-channel max(abs) over the spatial axes. Returns Float32Array of length C.
 * Caller guarantees latent.shape[0] = C and the rest is the spatial volume.
 */
export function computeScales(latent: Float32Array, shape: readonly number[]): Float32Array {
  const C = shape[0]!;
  const spatial = shape.slice(1).reduce((a, b) => a * b, 1);
  const out = new Float32Array(C);
  for (let c = 0; c < C; c++) {
    let m = 0;
    const off = c * spatial;
    for (let i = 0; i < spatial; i++) {
      const a = Math.abs(latent[off + i]!);
      if (a > m) m = a;
    }
    // Round to fp16 precision so the wire-side scales match the encoder.
    out[c] = f16ToF32(f32ToF16(m));
  }
  return out;
}

/**
 * Round-half-to-even (IEEE 754 roundTiesToEven), matching Python's
 * `numpy.rint`. JS's Math.round is round-half-away-from-zero, so we
 * implement it explicitly here.
 */
function rintTowardEven(x: number): number {
  const fl = Math.floor(x);
  const diff = x - fl;
  if (diff < 0.5) return fl;
  if (diff > 0.5) return fl + 1;
  return fl % 2 === 0 ? fl : fl + 1;
}

function quantizeSymmetric(
  latent: Float32Array, shape: readonly number[],
  scales: Float32Array, maxQ: number,
): Int8Array {
  const C = shape[0]!;
  const spatial = shape.slice(1).reduce((a, b) => a * b, 1);
  const out = new Int8Array(latent.length);
  for (let c = 0; c < C; c++) {
    const s = scales[c]!;
    const off = c * spatial;
    if (s === 0) continue;
    const inv = maxQ / s;
    for (let i = 0; i < spatial; i++) {
      const q = rintTowardEven(latent[off + i]! * inv);
      const clamped = q > maxQ ? maxQ : q < -maxQ ? -maxQ : q;
      out[off + i] = clamped;
    }
  }
  return out;
}

function quantizeInt8(latent: Float32Array, shape: readonly number[], scales: Float32Array): Int8Array {
  return quantizeSymmetric(latent, shape, scales, 127);
}

function quantizeInt4(latent: Float32Array, shape: readonly number[], scales: Float32Array): Int8Array {
  return quantizeSymmetric(latent, shape, scales, 7);
}

/**
 * Pack int4 values (each in [-7, +7]) two-per-byte, low nibble first.
 * The low nibble of byte k holds values[2k]; the high nibble holds
 * values[2k+1]. A trailing odd value zero-pads the high nibble.
 */
export function packInt4LowFirst(values: Int8Array): Uint8Array {
  const n = values.length;
  const padded = n % 2 === 1 ? n + 1 : n;
  const out = new Uint8Array(padded / 2);
  for (let k = 0; k < out.length; k++) {
    const lo = (values[2 * k] ?? 0) & 0x0f;
    const hi = (values[2 * k + 1] ?? 0) & 0x0f;
    out[k] = lo | (hi << 4);
  }
  return out;
}

/**
 * Inverse of `packInt4LowFirst`. The caller must know how many values were
 * packed (`expectedLen`) so a trailing odd-byte zero pad doesn't get
 * exposed as a stray value. Each nibble is decoded as a two's-complement
 * int4 in the range [-8, +7]; under the Codec saturating quantizer the
 * realised range is [-7, +7].
 */
export function unpackInt4LowFirst(bytes: Uint8Array, expectedLen: number): Int8Array {
  const out = new Int8Array(expectedLen);
  for (let i = 0; i < expectedLen; i++) {
    const byte = bytes[i >>> 1]!;
    const nib = (i & 1) === 0 ? byte & 0x0f : (byte >>> 4) & 0x0f;
    // Sign-extend from int4 → int8.
    out[i] = nib & 0x08 ? nib | 0xf0 : nib;
  }
  return out;
}

function saturatingDiff(a: Int8Array, b: Int8Array, maxQ: number): Int8Array {
  if (a.length !== b.length) {
    throw new Error(`saturatingDiff length mismatch: ${a.length} vs ${b.length}`);
  }
  const out = new Int8Array(a.length);
  for (let i = 0; i < a.length; i++) {
    const d = a[i]! - b[i]!;
    out[i] = d > maxQ ? maxQ : d < -maxQ ? -maxQ : d;
  }
  return out;
}

function saturatingAdd(a: Int8Array, b: Int8Array, maxQ: number): Int8Array {
  if (a.length !== b.length) {
    throw new Error(`saturatingAdd length mismatch: ${a.length} vs ${b.length}`);
  }
  const out = new Int8Array(a.length);
  for (let i = 0; i < a.length; i++) {
    const s = a[i]! + b[i]!;
    out[i] = s > maxQ ? maxQ : s < -maxQ ? -maxQ : s;
  }
  return out;
}

// ── Stateful encoder ────────────────────────────────────────────────────────

export interface LatentStreamEncoderOptions {
  latentSpaceId: string;
  shape: readonly number[];
  dtype: LatentDtype;
  pipeline: PipelineName;
  /** Required for `int8` and `int4` pipelines. Length must be shape[0]. */
  staticScales?: Float32Array;
  fps?: number;
  totalFrames?: number;
  vaeScaleFactor?: number;
}

/**
 * Server-side streaming encoder. One per outbound latent stream. Construct
 * with the negotiated `(latent_space_id, shape, dtype, pipeline)`, call
 * `header()` once, then `frame(latent, …)` per produced latent.
 *
 * Mirrors `LatentStreamEncoder` in `latent_frame.py`.
 */
export class LatentStreamEncoder {
  readonly latentSpaceId: string;
  readonly shape: readonly number[];
  readonly dtype: LatentDtype;
  readonly pipeline: PipelineName;
  readonly fps?: number;
  readonly totalFrames?: number;
  readonly vaeScaleFactor?: number;

  private readonly staticScales: Float32Array | null;
  private lastKeyframeQ: Int8Array | null = null;
  private lastKeyframeScales: Float32Array | null = null;
  private lastSeq = -1;

  constructor(opts: LatentStreamEncoderOptions) {
    if (!PIPELINE_NAMES.includes(opts.pipeline)) {
      throw new Error(
        `unknown pipeline ${JSON.stringify(opts.pipeline)}; ` +
          `must be one of ${PIPELINE_NAMES.join(', ')}`,
      );
    }
    if (STATIC_SCALE_PIPELINES.has(opts.pipeline) && !opts.staticScales) {
      throw new Error(
        `pipeline ${opts.pipeline} requires staticScales (per-channel fp16 array)`,
      );
    }
    if (!STATIC_SCALE_PIPELINES.has(opts.pipeline) && opts.staticScales) {
      throw new Error(
        `pipeline ${opts.pipeline} doesn't accept staticScales — ` +
          `scales travel per-keyframe`,
      );
    }
    if (opts.staticScales && opts.staticScales.length !== opts.shape[0]) {
      throw new Error(
        `staticScales must have length shape[0] = ${opts.shape[0]}; ` +
          `got ${opts.staticScales.length}`,
      );
    }
    this.latentSpaceId = opts.latentSpaceId;
    this.shape = [...opts.shape];
    this.dtype = opts.dtype;
    this.pipeline = opts.pipeline;
    this.fps = opts.fps;
    this.totalFrames = opts.totalFrames;
    this.vaeScaleFactor = opts.vaeScaleFactor;
    this.staticScales = opts.staticScales ?? null;
  }

  /** Encode the per-stream header. Call once, before any frame(). */
  header(): Uint8Array {
    const scalesBytes = this.staticScales ? scalesToBytes(this.staticScales) : undefined;
    return encodeLatentHeaderMsgpack({
      latent_space_id: this.latentSpaceId,
      shape: this.shape,
      dtype: this.dtype,
      pipeline: this.pipeline,
      scales: scalesBytes,
      fps: this.fps,
      total_frames: this.totalFrames,
      vae_scale_factor: this.vaeScaleFactor,
    });
  }

  /**
   * Encode one frame. `latent` is the raw fp32 tensor in channel-first
   * row-major order (shape == this.shape). `seq` is monotonic 0,1,2,…
   * Image streams emit a single frame with `seq=0, keyframe=true`.
   */
  frame(
    latent: Float32Array,
    opts: { seq: number; keyframe: boolean; done?: boolean; finishReason?: string },
  ): Uint8Array {
    if (opts.seq <= this.lastSeq) {
      throw new Error(
        `seq must be monotonically increasing; got ${opts.seq} after ${this.lastSeq}`,
      );
    }
    const expectedLen = this.shape.reduce((a, b) => a * b, 1);
    if (latent.length !== expectedLen) {
      throw new Error(
        `latent length ${latent.length} does not match shape product ${expectedLen}`,
      );
    }
    const data = this.encodePipeline(latent, opts.keyframe);
    this.lastSeq = opts.seq;
    return encodeLatentFrameMsgpack({
      data,
      seq: opts.seq,
      keyframe: opts.keyframe,
      done: opts.done ?? false,
      finish_reason: opts.finishReason,
    });
  }

  private encodePipeline(latent: Float32Array, keyframe: boolean): Uint8Array {
    const p = this.pipeline;

    if (p === 'raw') {
      return float32ArrayToTypedBytes(latent, this.dtype);
    }

    if (p === 'int8') {
      const q = quantizeInt8(latent, this.shape, this.staticScales!);
      return new Uint8Array(q.buffer, q.byteOffset, q.byteLength);
    }

    if (p === 'int4') {
      const q = quantizeInt4(latent, this.shape, this.staticScales!);
      return packInt4LowFirst(q);
    }

    if (p === 'int8-adaptive') {
      if (!keyframe) {
        throw new Error('int8-adaptive: every frame must be keyframe=true');
      }
      const scales = computeScales(latent, this.shape);
      const q = quantizeInt8(latent, this.shape, scales);
      return concat(scalesToBytes(scales), int8ArrayToBytes(q));
    }

    if (p === 'int4-adaptive') {
      if (!keyframe) {
        throw new Error('int4-adaptive: every frame must be keyframe=true');
      }
      const scales = computeScales(latent, this.shape);
      const q = quantizeInt4(latent, this.shape, scales);
      return concat(scalesToBytes(scales), packInt4LowFirst(q));
    }

    if (p === 'delta+int8') {
      if (keyframe) {
        const scales = computeScales(latent, this.shape);
        const q = quantizeInt8(latent, this.shape, scales);
        this.lastKeyframeQ = q;
        this.lastKeyframeScales = scales;
        return concat(scalesToBytes(scales), int8ArrayToBytes(q));
      }
      if (!this.lastKeyframeQ || !this.lastKeyframeScales) {
        throw new Error('delta+int8: first frame in stream must be keyframe=true');
      }
      const qNow = quantizeInt8(latent, this.shape, this.lastKeyframeScales);
      const residual = saturatingDiff(qNow, this.lastKeyframeQ, 127);
      return int8ArrayToBytes(residual);
    }

    if (p === 'delta+int4') {
      if (keyframe) {
        const scales = computeScales(latent, this.shape);
        const q = quantizeInt4(latent, this.shape, scales);
        this.lastKeyframeQ = q;
        this.lastKeyframeScales = scales;
        return concat(scalesToBytes(scales), packInt4LowFirst(q));
      }
      if (!this.lastKeyframeQ || !this.lastKeyframeScales) {
        throw new Error('delta+int4: first frame in stream must be keyframe=true');
      }
      const qNow = quantizeInt4(latent, this.shape, this.lastKeyframeScales);
      const residual = saturatingDiff(qNow, this.lastKeyframeQ, 7);
      return packInt4LowFirst(residual);
    }

    throw new Error(`unhandled pipeline ${p}`);
  }
}

// ── Inverse / decoder pipeline ──────────────────────────────────────────────

/**
 * Stateful decoder. Construct with the parsed `LatentStreamHeader`, then call
 * `decodeFrame(frame)` per incoming `LatentFrame`. Returns the reconstructed
 * fp32 tensor in channel-first row-major order, suitable for handing to a
 * VAE decoder. Bit-identical reconstruction at the latent-byte boundary
 * against the Python reference encoder (modulo fp16 rounding which both
 * sides handle identically).
 */
export class LatentStreamDecoder {
  readonly header: LatentStreamHeader;
  private readonly C: number;
  private readonly spatial: number;
  private staticScales: Float32Array | null;
  private lastKeyframeQ: Int8Array | null = null;
  private lastKeyframeScales: Float32Array | null = null;

  constructor(header: LatentStreamHeader) {
    if (!PIPELINE_NAMES.includes(header.pipeline)) {
      throw new Error(`unknown pipeline ${header.pipeline} on header`);
    }
    this.header = header;
    this.C = header.shape[0]!;
    this.spatial = header.shape.slice(1).reduce((a, b) => a * b, 1);
    if (STATIC_SCALE_PIPELINES.has(header.pipeline)) {
      if (!header.scales || header.scales.length !== 2 * this.C) {
        throw new Error(
          `pipeline ${header.pipeline} requires header.scales of length ${2 * this.C}`,
        );
      }
      this.staticScales = scalesFromBytes(header.scales);
    } else {
      this.staticScales = null;
    }
  }

  decodeFrame(frame: LatentFrame): Float32Array {
    const p = this.header.pipeline;
    const totalLen = this.C * this.spatial;

    if (p === 'raw') {
      return typedBytesToFloat32Array(frame.data, this.header.dtype, totalLen);
    }

    if (p === 'int8') {
      const q = bytesToInt8Array(frame.data, totalLen);
      return dequantize(q, this.staticScales!, this.C, this.spatial, 127);
    }

    if (p === 'int4') {
      const q = unpackInt4LowFirst(frame.data, totalLen);
      return dequantize(q, this.staticScales!, this.C, this.spatial, 7);
    }

    if (p === 'int8-adaptive') {
      const scales = scalesFromBytes(frame.data.subarray(0, 2 * this.C));
      const q = bytesToInt8Array(frame.data.subarray(2 * this.C), totalLen);
      return dequantize(q, scales, this.C, this.spatial, 127);
    }

    if (p === 'int4-adaptive') {
      const scales = scalesFromBytes(frame.data.subarray(0, 2 * this.C));
      const q = unpackInt4LowFirst(frame.data.subarray(2 * this.C), totalLen);
      return dequantize(q, scales, this.C, this.spatial, 7);
    }

    if (p === 'delta+int8') {
      if (frame.keyframe) {
        const scales = scalesFromBytes(frame.data.subarray(0, 2 * this.C));
        const q = bytesToInt8Array(frame.data.subarray(2 * this.C), totalLen);
        this.lastKeyframeScales = scales;
        this.lastKeyframeQ = q;
        return dequantize(q, scales, this.C, this.spatial, 127);
      }
      if (!this.lastKeyframeQ || !this.lastKeyframeScales) {
        throw new Error('delta+int8: first frame in stream must be a keyframe');
      }
      const residual = bytesToInt8Array(frame.data, totalLen);
      const qNow = saturatingAdd(this.lastKeyframeQ, residual, 127);
      return dequantize(qNow, this.lastKeyframeScales, this.C, this.spatial, 127);
    }

    if (p === 'delta+int4') {
      if (frame.keyframe) {
        const scales = scalesFromBytes(frame.data.subarray(0, 2 * this.C));
        const q = unpackInt4LowFirst(frame.data.subarray(2 * this.C), totalLen);
        this.lastKeyframeScales = scales;
        this.lastKeyframeQ = q;
        return dequantize(q, scales, this.C, this.spatial, 7);
      }
      if (!this.lastKeyframeQ || !this.lastKeyframeScales) {
        throw new Error('delta+int4: first frame in stream must be a keyframe');
      }
      const residual = unpackInt4LowFirst(frame.data, totalLen);
      const qNow = saturatingAdd(this.lastKeyframeQ, residual, 7);
      return dequantize(qNow, this.lastKeyframeScales, this.C, this.spatial, 7);
    }

    throw new Error(`unhandled pipeline ${p}`);
  }
}

function dequantize(
  q: Int8Array, scales: Float32Array,
  C: number, spatial: number, maxQ: number,
): Float32Array {
  const out = new Float32Array(q.length);
  for (let c = 0; c < C; c++) {
    const s = scales[c]!;
    const off = c * spatial;
    const factor = s / maxQ;
    for (let i = 0; i < spatial; i++) {
      out[off + i] = q[off + i]! * factor;
    }
  }
  return out;
}

// ── msgpack encoder / decoder ───────────────────────────────────────────────

/**
 * Encode a `LatentStreamHeader` as a single msgpack object. The first frame
 * of any latent stream MUST be a header; subsequent frames are
 * `LatentFrame`s.
 */
export function encodeLatentHeaderMsgpack(
  h: LatentStreamHeader & { type?: 'header' },
): Uint8Array {
  const msg: Record<string, unknown> = {
    type: 'header',
    latent_space_id: h.latent_space_id,
    shape: [...h.shape],
    dtype: h.dtype,
    pipeline: h.pipeline,
  };
  if (h.scales !== undefined) msg.scales = h.scales;
  if (h.fps !== undefined) msg.fps = h.fps;
  if (h.total_frames !== undefined) msg.total_frames = h.total_frames;
  if (h.vae_scale_factor !== undefined) msg.vae_scale_factor = h.vae_scale_factor;
  return msgpackEncode(msg);
}

export function encodeLatentFrameMsgpack(f: LatentFrame): Uint8Array {
  const msg: Record<string, unknown> = {
    data: f.data,
    seq: f.seq,
    keyframe: f.keyframe,
    done: f.done,
  };
  if (f.finish_reason !== undefined) msg.finish_reason = f.finish_reason;
  return msgpackEncode(msg);
}

/**
 * Parse one msgpack object as a `LatentStreamHeader`. Throws if it doesn't
 * look like a header (missing latent_space_id / shape / dtype / pipeline,
 * or `type !== 'header'` if `type` is present).
 */
export function decodeLatentHeaderMsgpack(bytes: Uint8Array): LatentStreamHeader {
  const obj = msgpackDecode(bytes) as Record<string, unknown>;
  if (typeof obj !== 'object' || obj === null) {
    throw new Error('header msgpack did not decode to an object');
  }
  if ('type' in obj && obj.type !== 'header') {
    throw new Error(`expected type:'header', got ${JSON.stringify(obj.type)}`);
  }
  const required = ['latent_space_id', 'shape', 'dtype', 'pipeline'];
  for (const k of required) {
    if (!(k in obj)) throw new Error(`header missing required field: ${k}`);
  }
  return {
    latent_space_id: String(obj.latent_space_id),
    shape: obj.shape as number[],
    dtype: obj.dtype as LatentDtype,
    pipeline: obj.pipeline as PipelineName,
    scales: obj.scales as Uint8Array | undefined,
    fps: obj.fps as number | undefined,
    total_frames: obj.total_frames as number | undefined,
    vae_scale_factor: obj.vae_scale_factor as number | undefined,
  };
}

export function decodeLatentFrameMsgpack(bytes: Uint8Array): LatentFrame {
  const obj = msgpackDecode(bytes) as Record<string, unknown>;
  if (typeof obj !== 'object' || obj === null) {
    throw new Error('frame msgpack did not decode to an object');
  }
  if (!(obj.data instanceof Uint8Array)) {
    throw new Error('frame.data must be a Uint8Array');
  }
  return {
    data: obj.data,
    seq: Number(obj.seq),
    keyframe: Boolean(obj.keyframe),
    done: Boolean(obj.done),
    finish_reason: typeof obj.finish_reason === 'string' ? obj.finish_reason : undefined,
  };
}

// ── Internal helpers ────────────────────────────────────────────────────────

function int8ArrayToBytes(arr: Int8Array): Uint8Array {
  return new Uint8Array(arr.buffer, arr.byteOffset, arr.byteLength);
}

function bytesToInt8Array(bytes: Uint8Array, expectedLen: number): Int8Array {
  if (bytes.length !== expectedLen) {
    throw new Error(`int8 byte length ${bytes.length} != expected ${expectedLen}`);
  }
  return new Int8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

function concat(...parts: Uint8Array[]): Uint8Array {
  let total = 0;
  for (const p of parts) total += p.length;
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  return out;
}

function float32ArrayToTypedBytes(latent: Float32Array, dtype: LatentDtype): Uint8Array {
  if (dtype === 'fp32') {
    return new Uint8Array(latent.buffer, latent.byteOffset, latent.byteLength);
  }
  if (dtype === 'fp16' || dtype === 'bf16') {
    // bf16 has no native JS support and is not used by SD-family VAEs at
    // raw-pipeline; treat as fp16 wire byte width to match the Python file's
    // mapping table. Servers using bf16 latents at raw should switch to a
    // quantizing pipeline.
    const out = new Uint8Array(latent.length * 2);
    const view = new DataView(out.buffer);
    for (let i = 0; i < latent.length; i++) {
      view.setUint16(i * 2, f32ToF16(latent[i]!), true);
    }
    return out;
  }
  if (dtype === 'int8') {
    const out = new Int8Array(latent.length);
    for (let i = 0; i < latent.length; i++) {
      const r = rintTowardEven(latent[i]!);
      out[i] = r > 127 ? 127 : r < -128 ? -128 : r;
    }
    return new Uint8Array(out.buffer, out.byteOffset, out.byteLength);
  }
  if (dtype === 'int4') {
    const arr = new Int8Array(latent.length);
    for (let i = 0; i < latent.length; i++) {
      const r = rintTowardEven(latent[i]!);
      arr[i] = r > 7 ? 7 : r < -7 ? -7 : r;
    }
    return packInt4LowFirst(arr);
  }
  throw new Error(`unsupported raw-pipeline dtype: ${dtype}`);
}

function typedBytesToFloat32Array(
  bytes: Uint8Array, dtype: LatentDtype, expectedLen: number,
): Float32Array {
  if (dtype === 'fp32') {
    return new Float32Array(bytes.buffer, bytes.byteOffset, expectedLen);
  }
  if (dtype === 'fp16' || dtype === 'bf16') {
    const out = new Float32Array(expectedLen);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    for (let i = 0; i < expectedLen; i++) {
      out[i] = f16ToF32(view.getUint16(i * 2, true));
    }
    return out;
  }
  if (dtype === 'int8') {
    const i8 = new Int8Array(bytes.buffer, bytes.byteOffset, expectedLen);
    const out = new Float32Array(expectedLen);
    for (let i = 0; i < expectedLen; i++) out[i] = i8[i]!;
    return out;
  }
  if (dtype === 'int4') {
    const i4 = unpackInt4LowFirst(bytes, expectedLen);
    const out = new Float32Array(expectedLen);
    for (let i = 0; i < expectedLen; i++) out[i] = i4[i]!;
    return out;
  }
  throw new Error(`unsupported raw-pipeline dtype: ${dtype}`);
}

// Re-exports for ergonomic single-import access.
export { f32ToF16, f16ToF32 };
// `INT4_PIPELINES`, `DELTA_PIPELINES`, etc. are intentionally NOT exported —
// callers who need to introspect should switch on `pipeline` directly.
